/* 教材级正文：把 78 讲从「提纲」补成可照着练的正文与带解析的判定题。
   数据独立于机器生成的课程表，便于继续扩充。 */
(() => {
  'use strict';
  const C = window.ZIPING_CONTENT;
  if (!C) return;
  const P = [{"id":"L01","b":"一张盘可以从五个层面说「对」，混在一句话里就永远吵不清。这一讲先把五个层面切开，后面所有的争论才有地方落。","h":"把一句断语拆成五层","p":["计算正确：给定输入与约定，四柱、藏干、十神能被人照着复算出来，错一位就是错。这一层没有流派，只有算法与实现，是这个站全部内容的地基。","取法正确：旺衰怎么加权、格局怎么定成败、用神先看调候还是先看扶抑，各有家法。同一张盘两种取法结论相反，都可以是「对的取法」，前提是你写明用的是哪一套。","表述正确：说「若单位有岗位变动，2024 年较易被提名」还是说「你 2024 年必升职」。前者有方向、有窗口、可被现实推翻；后者不可证伪，等于什么都没说。","预测正确：只有把结论事先写下来、事后逐条对，才算验证。事后回想「好像挺准」不算，因为你会自动记住说中的、忘掉说不中的。"],"s":["写下你想说的那句断语，原话不动。","标出它属于哪一层：计算、取法、表述、预测。","若它声称是预测，补上检验方式与时间窗。","若几层混在一句里，拆成几句重写。"],"e":"「你今年必定升职」这句话，计算层根本支持不了——盘里没有「升职」这个字；取法层最多能说「官星受生、印来护官」；表述层应写成「若单位今年有岗位调整，你被提名的概率高于同侪」；预测层要把它存底，年底核对。四层各自成立，才谈得上「准」。","pr":"拿你最近读到或听到的一句断语，拆成五层，指出它缺哪一层、缺了会怎样。","q":[{"question":"程序把四柱算得完全正确，能否据此推出「明年必升职」？","options":["能，四柱对就等于断语对","不能，计算正确只保证第一步","只要断语写得长就能"],"answer":"不能，计算正确只保证第一步","explanation":"计算层只保证四柱、藏干、十神可复算；能不能升职属于现实事件，需要另设检验，不能由计算正确直接推出。"},{"question":"下面哪一句是可检验的表述？","options":["你命里带财，早晚会富","若明年岗位有调整，你较易被提名","你这个人就是不适合打工"],"answer":"若明年岗位有调整，你较易被提名","explanation":"可检验的表述必须有条件、有方向、有窗口，能被现实推翻。另两句没有时间窗也没有可核对的方向。"}]},{"id":"L02","b":"资料表不是填得越满越好，而是要让第二个人拿着它，能复算出和你一模一样的一张盘。","h":"六项必填与三项必标","p":["六项必填：公历日期、出生时刻（尽量到分）、性别、出生地（到区县）、记录来源、时刻精度。缺任何一项，后面的结论都要相应打折。","三项必标：来源是出生证还是家人口述；口述要写「大约」的范围，不要替对方决定；时区写 IANA 名称（Asia/Shanghai），不要只写「北京时间」。","精度分三级：到分、到小时、只知上午下午。到小时的，时柱可能跨两个；只知上午下午的，时柱基本不可用，必须先验盘再谈判断。","记录里最容易被改写的有两处：把「卯时左右」写成「06:30」，把新疆的钟表读数直接当东经 120° 的太阳时。两处都会让盘看起来很精确，实际上是错的。"],"s":["逐项抄录，不替当事人「修正」措辞。","标出来源与精度等级。","换算成 IANA 时区，并记录出生地经度。","精度不足时，列出候选时辰，先不下单一结论。"],"e":"口述「天亮前后，鸡叫过一会儿」——记为「约 05:00—06:00，口述，精度 ±1 小时」，候选卯时与寅时两张盘并列。若直接写成 06:30，就等于替当事人编了一个精确时刻，后面所有「准」都没有意义。","pr":"给自己或家人建一张资料表，必须写出「哪一项不确定」以及不确定的程度。","q":[{"question":"口述「卯时左右」，正确的记录方式是？","options":["直接记 06:30","记「约 05:00—07:00，口述，±1 小时」","只写「卯时」不写钟点"],"answer":"记「约 05:00—07:00，口述，±1 小时」","explanation":"保留区间与来源，才不把不确定伪装成精确。只写「卯时」丢失了钟表读数这条原始信息。"},{"question":"只知道「上午出生」的记录，第一步应当做什么？","options":["按 09:00 起盘","列出候选时辰并用已知事件验盘","直接放弃这张盘"],"answer":"列出候选时辰并用已知事件验盘","explanation":"上午可能跨三个时辰，时柱不定就不能谈六亲与晚景；先验盘是唯一负责任的做法。"}]},{"id":"L03","b":"同一个钟点在不同时区是不同的瞬间；中国 1986—1991 年的夏令时还会把钟拨快一小时。这两件事都不处理，后面的柱子全是浮的。","h":"先定瞬间，再谈钟点","p":["时区的唯一作用，是把「钟表读数」换成一个确定的世界时刻。中国的 IANA 名是 Asia/Shanghai，UTC+8。新疆也用这个时区名，但那只是行政统一，不代表当地太阳也在东经 120°。","中国在 1986—1991 年实行夏令时：每年 4 月中旬到 9 月中旬，钟表比标准时快 1 小时。这几年夏季出生的人，若记录是钟表读数，必须先减 1 小时。","其他国家的夏令时规则各不相同，而且历史上有过多次变更。不要背规则，要查该时区在该日期的实际偏移——这一步用 IANA 数据最可靠。","顺序不能合并：先判断是否落在夏令时区间并还原标准时，再做经度与均时差修正。反过来做，会把两个修正项混成一个数，出错也查不出来。"],"s":["查出生地该日的 UTC 偏移。","若落在夏令时区间，钟表读数减 1 小时。","得到地方标准时。","把标准时交给下一步做真太阳时修正。"],"e":"1988-07-15 14:00 生于上海。1988 年 7 月属夏令时，标准时是 13:00。若不还原，后面按经度算真太阳时会平白多出 60 分钟，原本的未时可能被推到申时，时柱整柱错位。","pr":"找一位 1986—1991 年夏季出生的亲友，问清当时的钟表读数，还原出标准时，再与网页结果对照。","q":[{"question":"1988 年 7 月上海出生记录为 14:00，标准时应为？","options":["14:00","13:00","15:00"],"answer":"13:00","explanation":"1988 年 7 月处于中国夏令时区间，钟表比标准时快 1 小时，故减 1 小时。"},{"question":"新疆使用 Asia/Shanghai 时区，是否意味着不需要经度校正？","options":["需要，行政时区不等于太阳位置","不需要，时区已统一"],"answer":"需要，行政时区不等于太阳位置","explanation":"时区只解决瞬间换算；太阳位置由经度决定，乌鲁木齐与东经 120° 差 32° 以上，必须校正。"}]},{"id":"L11","b":"钟表时是行政时间，真太阳时是太阳的实际位置。两者之间隔着两个修正项，各管一件事，缺一个都不叫真太阳时。","h":"两个修正项，各管一件事","p":["经度差：每偏离时区标准经线 1° 折 4 分钟。中国标准经线是东经 120°，乌鲁木齐 87.62°，差 32.38°，折 129.5 分钟。这一项是固定的，只与经度有关。","均时差：地球轨道是椭圆、黄赤交角存在，真太阳时与平太阳时全年最多差约 ±16 分钟。2 月中旬约 −14 分，11 月初约 +16 分。这一项随日期变，必须查当日数值。","两项相加才是真太阳时。只做经度差，得到的是「地方平太阳时」，仍不是真太阳时——很多排盘软件就停在这一步，却标成真太阳时。","时柱只看落在哪个时辰，所以差几分钟常常不改柱。但靠近时辰边界时必须算：差 1 分钟就可能整柱错，而时柱管子女、晚景与合作，错一位结论全变。"],"s":["取出生地实际经度（不是省会）。","算（经度 − 120）× 4，得经度差。","查当日均时差。","两项相加得真太阳时，再看落在哪个时辰。"],"e":"杭州 12:00：经度 120.16°，经度差 +0.6 分，均时差约 +1.1 分，真太阳时 12:01.7，仍在午时中段，时柱不变。乌鲁木齐 12:00：真太阳时约 09:51，从午时退回巳时，甲午变癸巳。同一个「中午 12 点」，西边的人其实才上午十点不到。","pr":"用自己出生地算一遍，写出四个数：经度、经度差、均时差、真太阳时。再说明时柱有没有变、为什么。","q":[{"question":"经度每偏离标准经线 1°，折合多少分钟？","options":["1 分钟","4 分钟","15 分钟"],"answer":"4 分钟","explanation":"地球 24 小时转 360°，即 1° 折 4 分钟，这是经度时差的基本换算。"},{"question":"只做经度差修正、不做均时差修正，得到的是？","options":["真太阳时","地方平太阳时","民用钟表时"],"answer":"地方平太阳时","explanation":"真太阳时 = 平太阳时 + 均时差；只做经度差仍是平太阳时，最多差十几分钟。"}]},{"id":"L04","b":"元旦不是命理年的起点，农历正月初一也不是。命理年只认立春，而且认到分钟。","h":"三套「年」要分清","p":["公历年从 1 月 1 日起，农历年从正月初一起，命理年从立春起。三者互不同步，最多能差一个多月。你把农历年当命理年，1 月出生的人年柱就会错。","立春多在 2 月 3—5 日，交节时刻精确到分。出生在交节之前，年柱仍属上一年；交节之后才进新年。同一小时里前后差 10 分钟，年柱可以不同。","农历有闰月，但闰月不额外生成一个月柱。月柱只随十二节走，所以「闰四月」不会让你多出一个巳月。这一点最容易被「闰月」这个词带偏。","操作顺序：先算出生的 UTC 瞬间，再与该年立春瞬间比较，大者为新年。不要用当地日历日直接比，节假日与跨时区都会骗你。"],"s":["查出生年立春的交节时刻。","把出生时间换算成同一时间基准。","比较先后，定年柱。","再查出生落在哪个节之后，定月柱。"],"e":"2024 年立春是 2 月 4 日 16:27:07。同日 14:00 出生仍是癸卯年乙丑月，18:00 出生已是甲辰年丙寅月——年柱与月柱同时换。这一天出生的人，记录差一小时就是两张完全不同的盘。","pr":"找一张立春当天出生的盘，把交节前后的两组年柱、月柱都写出来，并说明你的记录精度够不够判断。","q":[{"question":"命理年柱以什么为界？","options":["公历 1 月 1 日","农历正月初一","立春"],"answer":"立春","explanation":"年柱只认立春；农历年服务农历日期，不服务命理年柱。"},{"question":"闰月是否会额外生成一个月柱？","options":["会，闰月算一个月","不会，月柱只随十二节走"],"answer":"不会，月柱只随十二节走","explanation":"月柱的分界是十二节，闰月不改变节的位置，故不额外成柱。"}]},{"id":"L05","b":"月柱不按初一换，按十二节换；月干也不是查出来的，是由年干用五虎遁推出来的。","h":"节不是气，只认节","p":["十二节：立春、惊蛰、清明、立夏、芒种、小暑、立秋、白露、寒露、立冬、大雪、小寒。雨水、春分、谷雨这些是「气」，气不换月。把气当节，月柱就会整月错。","月支是固定的：立春起寅，惊蛰起卯，清明起辰，一路到小寒起丑。所以月支其实就是「第几个节之后」，与农历月份无关。","月干用五虎遁：甲己之年丙作首，乙庚之岁戊为头，丙辛必定寻庚起，丁壬壬位顺行流，戊癸之年甲寅求。记住这五句，比查表快。","交节当天出生必须查时刻。差几分钟就可能换月，而月令是旺衰的第一权重——月令一换，旺衰、格局、用神全部要重判。"],"s":["定出生在哪个节之后。","按节取月支。","用五虎遁从年干推月干。","交节日查交节分钟，决定属于哪个月。"],"e":"乙年：五虎遁「乙庚之岁戊为头」，寅月为戊寅，顺推己卯、庚辰、辛巳、壬午、癸未、甲申、乙酉、丙戌、丁亥、戊子、己丑。注意子月从「大雪」起，不是冬至——冬至是气。","pr":"手推某一年的十二个月柱，与网页逐个对照；再找一个交节当天的出生记录，说明差多少分钟会换月。","q":[{"question":"月柱的分界是？","options":["农历初一","十二节","中气"],"answer":"十二节","explanation":"月柱随十二节换，中气（雨水、春分等）不换月。"},{"question":"乙年的寅月，月干是什么？","options":["丙","戊","庚"],"answer":"戊","explanation":"五虎遁「乙庚之岁戊为头」，乙年寅月起戊寅。"}]},{"id":"L06","b":"十个字先分五行，再分阴阳。五行决定生克，阴阳决定十神的方向——同一个五行，阴阳一变，十神就换。","h":"先记属性，再记关系","p":["五行：甲乙木、丙丁火、戊己土、庚辛金、壬癸水。阴阳：甲丙戊庚壬为阳，乙丁己辛癸为阴。这二十个属性必须做到不假思索。","阴阳的作用在十神上：克我者，异性为正官、同性为七杀；我克者，异性为正财、同性为偏财；生我者，异性为正印、同性为偏印；我生者，异性为伤官、同性为食神。","比肩劫财是唯一的例外方向：同五行同性为比肩，同五行异性为劫财。记错这一条，四个十神会连锁出错。","天干的五行不因坐支而改。甲坐申仍是甲木，只是根弱；不要把「甲申」读成金。坐支只影响力量，不改变属性。"],"s":["写出十天干的五行。","标出阴阳（单数阳、双数阴）。","与日主比生克关系：生我、我生、我克、克我、同我。","按阴阳定正偏，得十神。"],"e":"日主辛（阴金）：见丙（阳火）——火克金、阴阳异性，为正官；见丁（阴火）——火克金、阴阳同性，为七杀；见壬（阳水）——金生水、异性，为伤官；见癸（阴水）——同性，为食神。四个字，两条规则，全部推得出来。","pr":"自定一个日主，随机抽三个天干，要求 3 秒内说出十神，并说出理由（生我/我生/我克/克我/同我 + 阴阳）。","q":[{"question":"甲在五行阴阳上属于？","options":["阳木","阴木","阳土"],"answer":"阳木","explanation":"甲乙同属木，甲为单数故阳。"},{"question":"日主辛见丙，十神是？","options":["正官","七杀","正印"],"answer":"正官","explanation":"丙火克辛金为「克我」，辛阴丙阳异性，故为正官。"}]},{"id":"L07","b":"地支是盘子，藏干是盘子里的东西。判根气看藏干，不看地支的字面——这是旺衰能不能判对的分水岭。","h":"本气、中气、余气","p":["十二支的本气：子水、丑土、寅木、卯木、辰土、巳火、午火、未土、申金、酉金、戌土、亥水。四正是纯气，四生、四墓是杂气。","藏干分三层：本气当令，力量最大；中气次之；余气最弱。如寅藏甲丙戊，甲为本气；辰藏戊乙癸，戊为本气，乙为中气，癸为余气。","结构上有规律：四生（寅申巳亥）多藏三干，四正（子午卯酉）多只藏本气，四墓（辰戌丑未）藏本气加中余。用这个规律记，比逐条背省力。","「通根」就是天干在地支藏干里找到同类。藏干里没有同类，天干再亮也是虚的；藏干里有，但落在年支或时支，力量不如坐支。位置和有无，要分开说。"],"s":["写出十二支藏干全表。","标出每支的本气。","判断某天干是否通根、通在哪一支。","记录位置：坐支、月支还是年时支。"],"e":"甲木：见寅为通根（寅藏甲，本气），力最实；见卯为得地（卯为木之旺），力也强；见辰藏乙为余气之根，力弱；见申（藏庚壬戊）则无根，甲虽透干而虚。同样叫「有木」，四种情况判旺衰时不能等同。","pr":"默写十二支藏干，错一个补三遍；再挑三个天干，分别判断在四支上的通根强弱。","q":[{"question":"辰的本气是什么？","options":["乙","戊","癸"],"answer":"戊","explanation":"辰藏戊乙癸，戊土为本气，乙为中气，癸为余气。"},{"question":"天干甲坐申，是否通根？","options":["有根，申中藏甲","无根，申藏庚壬戊"],"answer":"无根，申藏庚壬戊","explanation":"申中不藏甲，故甲坐申为无根，只有金生水、水生木的间接关系。"}]},{"id":"L08","b":"干支只能阳配阳、阴配阴，六十组一轮。知道这条，就不会写出「甲丑」这种根本不存在的组合。","h":"合法组合与旬","p":["天干 10、地支 12，最小公倍数 60，所以是六十甲子而不是一百二十。配对只取同阴阳，阳干只配阳支，阴干只配阴支。","每 10 组为一旬，旬首分别是甲子、甲戌、甲申、甲午、甲辰、甲寅。旬首的意思是「这一旬从哪个甲开始」。","空亡的求法：该旬旬首所「欠」的两个地支。甲子旬走到癸酉为止，戌亥没排上，所以戌亥空亡。这不是查表，是数出来的。","三个用途：校验排盘（不会出现非法组合）、推旬空、排大运流年时对位。空亡只表示该支力量减弱，不能直接断事。"],"s":["确定某柱属于哪一旬。","写出该旬旬首。","数出该旬欠的两个支，即空亡。","校验干支阴阳是否一致。"],"e":"甲子旬：甲子、乙丑、丙寅、丁卯、戊辰、己巳、庚午、辛未、壬申、癸酉，共 10 组，欠戌亥，故戌亥空。若某柱是甲戌，则它属甲戌旬，该旬空亡是申酉——空亡跟着旬走，不跟着年份走。","pr":"写出六旬的旬首与各自空亡；再随手写十个干支，标出哪几个是非法的。","q":[{"question":"「甲丑」这个组合存在吗？","options":["存在","不存在，阴阳不同不能配"],"answer":"不存在，阴阳不同不能配","explanation":"甲为阳干、丑为阴支，干支只取同阴阳相配，故不存在。"},{"question":"甲子旬的空亡是哪两支？","options":["戌亥","申酉","午未"],"answer":"戌亥","explanation":"甲子旬排到癸酉，欠戌亥两支，故戌亥空亡。"}]},{"id":"L09","b":"年看立春、月看节、日靠累算、时靠日干推。四柱各有各的算法，一把抓必错。","h":"四步各归各的","p":["年柱与月柱：都以「与节令瞬间比较」定，年比立春，月比十二节，月干再用五虎遁推。这两柱依赖的是天文时刻，不是日历。","日柱：以某一个甲子日为锚，按天数累算。跨时区、跨换日口径时，取的是「命理日」，不是当地日历日——这是最容易错的一步。","时柱：由日干起时干，用五鼠遁——甲己还加甲，乙庚丙作初，丙辛从戊起，丁壬庚子居，戊癸壬子是真途。日干一变，十二个时干全变。","顺序不能反：日柱不定则时干无从起；月柱不定则旺衰无从判。所以永远先定前三柱，最后推时柱。"],"s":["把出生读数换算成确定的瞬间。","与立春比，定年柱。","与十二节比，定月柱。","算日柱，再由日干推时干。"],"e":"辛日 08:37：五鼠遁「丙辛从戊起」，子时戊子、丑己丑、寅庚寅、卯辛卯，08:37 落辰时则为壬辰。若换日口径改成 23:00，日干可能变，十二个时干要全部重推。","pr":"任取一天，从日柱手推十二个时辰的时干，与网页对照；再换一次换日口径，看哪几个时干变了。","q":[{"question":"时干由什么推出来？","options":["日干","年干","月干"],"answer":"日干","explanation":"五鼠遁以日干起子时，故时干随日干变。"},{"question":"辛日的子时，时干是什么？","options":["戊","庚","壬"],"answer":"戊","explanation":"五鼠遁「丙辛从戊起」，辛日子时为戊子。"}]},{"id":"L10","b":"23:00 起就是子时，但日柱要不要跟着换，是约定不是算术。这一讲把三件事分开：什么时候是子时、日柱换不换、时干用哪天的日干起。","h":"三件事要分开","p":["子时分两段：23:00—24:00 是晚子时（子初），00:00—01:00 是早子时（子正）。两段都叫子时，但落在不同的日历日上。","换日口径有两种：00:00 换日（晚子时仍属当日），23:00 换日（晚子时已入次日）。本页默认前者，并提供后者做对照。这是流派约定，不是谁算错了。","时干还有第三种口径：晚子时用当日日干起，还是用次日日干起。这一项与换日口径相互独立，可以交叉出四种组合，报告里必须写清用了哪一种。","影响面很大：日柱一变，日主变、十神全变、夫妻宫变、起运顺逆也可能变。所以晚子时出生的人，报告首页必须先写口径，再谈判断。"],"s":["看时刻是否落在 23:00—24:00。","标出采用的换日口径。","标出晚子时的起干口径。","两种口径并列写出四柱差异。"],"e":"1995-06-15 23:30 生于北京：按 00:00 换日得丁丑日壬子时；按 23:00 换日得戊寅日壬子时。日柱差一位，日主从丁火变戊土，全部十神重排——这不是细节，是两张盘。","pr":"找一张晚子时出生的盘，把两种换日口径的四柱都写出来，标出哪几柱变了、日主变没变。","q":[{"question":"晚子时指的是哪个时段？","options":["23:00—24:00","00:00—01:00","22:00—23:00"],"answer":"23:00—24:00","explanation":"23:00 起进入子时，23—24 点为晚子时（子初），0—1 点为早子时（子正）。"},{"question":"日柱在 23:00 换还是 00:00 换，属于？","options":["计算错误","流派约定"],"answer":"流派约定","explanation":"两种口径都自洽，差别在约定；关键是写明用哪一套，不能两头取利。"}]},{"id":"L12","b":"十神不是十个名词，是「日主与另一个字」的十种相对关系。会推的人三秒一个，不会推的人背表还背错。","h":"三步推出十神，不用背表","p":["第一步定方向：以日主为中心，看目标字是「生我、我生、我克、克我、同我」哪一类。方向只有五个，先定方向就不会乱。","第二步定阴阳：目标字与日主同性还是异性。同性偏、异性正——这是四个「正偏」对的通用规则。","第三步取名：生我者印（正印/偏印），我生者食伤（伤官/食神），我克者财（正财/偏财），克我者官杀（正官/七杀），同我者比劫（比肩/劫财）。","两个必须记住的例外：同我这一类是「同性比肩、异性劫财」，与正偏规则相反；日干本身不取十神，写成「日主」或「元男/元女」。地支要取十神，必须先透出所藏天干，不能拿地支直接比。"],"s":["写日主，标阴阳。","对目标字判五类方向中的一类。","判同性还是异性，定正偏。","按方向取名，检查是否踩到比劫例外。"],"e":"日主甲（阳木）。庚：金克木属「克我」，庚阳与甲阳同性 → 七杀。辛：克我、异性 → 正官。戊：木克土属「我克」，同性 → 偏财。己：我克、异性 → 正财。丙：木生火属「我生」，同性 → 食神。丁：我生、异性 → 伤官。壬：水生木属「生我」，同性 → 偏印。癸：生我、异性 → 正印。乙：同我、异性 → 劫财。","pr":"以甲为日主，默写其余九干的十神；再换丙为日主重做一遍，检查有没有靠背表。","q":[{"question":"日主甲见庚，十神是？","options":["正官","七杀","偏财"],"answer":"七杀","explanation":"庚金克甲木为克我，甲阳庚阳同性，故为七杀。"},{"question":"「同我」这一类中，与日主异性的是什么？","options":["比肩","劫财"],"answer":"劫财","explanation":"同我者同性为比肩、异性为劫财，与其余四类的正偏规则相反。"}]},{"id":"L49","b":"十天干总表不是用来背的，是用来校验的。推完十神拿它对一眼，比反复背表可靠。","h":"以甲为样板，横向迁移","p":["先做一张完整的甲日主表：甲比肩、乙劫财、丙食神、丁伤官、戊偏财、己正财、庚七杀、辛正官、壬偏印、癸正印。这一行是所有推导的样板。","换日主时不要重背，只要看「同类位置的阴阳有没有翻转」。日主从阳干换到阴干（甲→乙），正偏全部对调：食神变伤官、正财变偏财、正官变七杀。","再换五行时，整行按相生顺序平移：木日主→火日主，食伤位置换成土。平移的规则就是五行相生，不必逐格重推。","总表最容易错的两格：一是戊己土对木日主是财还是官，二是壬癸水对火日主是官还是印。这两格搞反，整个盘的口径就全反。"],"s":["写出甲日主的十神全表。","换一个同五行、异阴阳的日主，把正偏对调。","换一个相生五行的日主，整行平移。","用具体盘校验两格易错位。"],"e":"以甲为样板推丙日主：丙火，生我者木（甲乙），我生者土（戊己），我克者金（庚辛），克我者水（壬癸），同我者火（丙丁）。丙阳：甲偏印、乙正印、戊食神、己伤官、庚偏财、辛正财、壬七杀、癸正官、丁劫财。全部由位置关系得出，未查表。","pr":"不查表，从甲日主表推出丙、戊两个日主的十神全表，再与网页逐格对照，记下错了哪几格。","q":[{"question":"日主丙见壬，十神是？","options":["正官","七杀","偏印"],"answer":"七杀","explanation":"壬水克丙火为克我，丙阳壬阳同性，故七杀。"},{"question":"日主从甲换成乙，原本的「正财」会变成？","options":["正财不变","偏财","正官"],"answer":"偏财","explanation":"阴阳翻转后正偏对调，正财变偏财。"}]},{"id":"L50","b":"生不总吉，克不总凶。五行生克里真正要判断的是「够不够」和「通不通」，不是贴上吉凶标签。","h":"生克是力量关系，不是道德判断","p":["相生：木生火、火生土、土生金、金生水、水生木。相克：木克土、土克水、水克火、火克金、金克木。这十条是全部推演的地基。","生过头会变成害：土多金埋、水多木浮、木多火塞、火多土焦、金多水浊。所以「有印生身」不等于好，「印太重」反而压住日主。","克也不总是坏事：身旺需要官杀来约束，财旺需要比劫来分担。判断克是好是坏，前提是先判出日主强弱——顺序不能倒。","真正要写的是三件事：谁生谁、力量够不够、中间有没有阻隔。写不出这三点，「生克吉凶」就只是口号。"],"s":["标出两字之间的生克方向。","估力量：透干还是藏支、有根还是无根。","看是否有第三字阻隔或通关。","结合日主强弱，再判是助还是耗。"],"e":"己土生辛金，是「生」。但若土有五六个而金只有一个，就成土多金埋：金被厚土闷住，反而不透。这时「生」要读成「压」，取用该取木疏土、水润土，而不是继续加土。","pr":"找一张印重的盘，数清印与日主的数量比，写出「生」在这里是助还是压，并给出理由。","q":[{"question":"「土多金埋」说明什么？","options":["生总是吉","生过头会变成压制","土不能生金"],"answer":"生过头会变成压制","explanation":"生克是力量关系，过了量就转向反面，土厚则金不透气。"},{"question":"判断「官杀克身」是吉是凶，前提是什么？","options":["先看官杀有几个","先判日主强弱","先看有没有印"],"answer":"先判日主强弱","explanation":"身旺喜克、身弱忌克，离开强弱谈克之吉凶没有意义。"}]},{"id":"L51","b":"天干之间只有两种关系：五合与相克。四冲是相克里最烈的一组，不是另立一类。","h":"合先于克，克分轻重","p":["天干五合：甲己合土、乙庚合金、丙辛合水、丁壬合木、戊癸合火。合是「牵住」，能不能化另说（见「合与化的条件」一讲）。","天干四冲：甲庚、乙辛、丙壬、丁癸。这四组既是相克，又同为阳克阳或阴克阴，力量最直接。戊己土没有冲，因为同性相克里没有对应的对立位。","其余相克：木克土（甲乙克戊己）、土克水、水克火、火克金、金克木。相克不等于相冲，冲强调正面对撞，克只讲方向。","判断顺序：先看有没有合（合能解克），再看克的方向与力度，最后看被克的一方有没有根。有合无合，结论常常相反。"],"s":["列出天干五合与四冲。","检查盘中是否成合、是否被合住。","标出相克的方向与力度。","看被克方有无根、有无救。"],"e":"甲见己为合（甲己合土），甲见庚为冲（甲庚相冲）。若盘中甲、己、庚同时透出，先论甲己合：合住之后庚金克甲的力量被分走一部分，这就是「合能解冲」的常见形态。","pr":"写一张天干关系表：五合、四冲、其余相克，各举一例；再找一个三字同时出现的盘，说明合与冲的先后。","q":[{"question":"下列哪一组是天干相冲？","options":["甲己","甲庚","丙辛"],"answer":"甲庚","explanation":"甲庚同为阳、金克木，属四冲之一；甲己是合，丙辛是合。"},{"question":"盘中同时出现甲、己、庚，应先论什么？","options":["先论甲庚冲","先论甲己合","先论己生庚"],"answer":"先论甲己合","explanation":"合的牵制优先于克，合住之后冲的力量才谈得上被分走。"}]},{"id":"L52","b":"十二地支既是方位、也是季节、也是藏干的容器。判旺衰时用季节，判根气时用藏干，两套用法不能混。","h":"一支三用：方位、季节、藏干","p":["季节：寅卯辰为春（木旺）、巳午未为夏（火旺）、申酉戌为秋（金旺）、亥子丑为冬（水旺）。辰戌丑未四季末各十八日属土，是「土旺」的由来。","本气：子水、丑土、寅木、卯木、辰土、巳火、午火、未土、申金、酉金、戌土、亥水。判月令旺衰看的是月支本气，不是月支里随便哪个藏干。","藏干：寅藏甲丙戊、卯藏乙、辰藏戊乙癸、巳藏丙庚戊、午藏丁己、未藏己丁乙、申藏庚壬戊、酉藏辛、戌藏戊辛丁、亥藏壬甲。四正多只藏本气。","两套用法分开：说「月令」时看季节与当令五行，说「通根」时看藏干里有没有同类。混着用，就会出现「月支有根所以身旺」这类错判。"],"s":["写月支，定当令五行。","写月支本气，核对是否与当令一致。","列各支藏干，判天干通根。","分别记录「得令」与「得地」的结论。"],"e":"辰月：当令为土（四季末），本气戊土；藏戊乙癸，乙为余气之木、癸为余气之水。若日主是乙木，辰月为「不得令」，但辰藏乙可作余气之根——得令与得地在这里给出两个不同答案，必须分开写。","pr":"取一张盘，把月令季节、月支本气、各支藏干、天干通根四项分别写出来，不许合成一句。","q":[{"question":"判月令旺衰，看的是月支的什么？","options":["任一藏干","本气","地支字面"],"answer":"本气","explanation":"月令以本气当令定旺衰，余气中气只在判通根时才用。"},{"question":"辰月对乙木日主而言，属于？","options":["得令","不得令但藏有余气之根"],"answer":"不得令但藏有余气之根","explanation":"辰当令为土，乙木不得令；但辰藏乙，可作余气之根，两者要分开写。"}]},{"id":"L53","b":"六合是牵住，三合是聚气，三会是成方。三种「合」的成立条件与力量都不同，混着说就会把「见合」当成「必发」。","h":"三种合，三种力量","p":["六合：子丑合土、寅亥合木、卯戌合火、辰酉合金、巳申合水、午未合土。六合是两支相牵，多主「拉扯、牵连」，力量小于三合。","三合：申子辰合水、亥卯未合木、寅午戌合火、巳酉丑合金。三合是长生—帝旺—墓的气聚，需三支齐见；只见两支叫半合，力量减半，且要看所缺的是不是旺支。","三会：寅卯辰会东方木、巳午未会南方火、申酉戌会西方金、亥子丑会北方水。三会是方位之气全，力量最整，也最怕被冲。","成立的三个条件：三支齐见、月令不逆、无强冲来破。三条缺一条，就只写「见合」不写「成局」。这是初学者最容易跳过的一步。"],"s":["列出盘中所有合的组合。","判断是三合、半合、六合还是会局。","检查月令与冲，判断是否真成。","写明合住或合成了什么（哪一五行、哪一宫）。"],"e":"庚午 己丑 壬寅 庚戌：支为午、丑、寅、戌，寅午戌三支齐见，三合火局成立，火即财。日主壬水仅 28 分偏弱，财局成而身弱——结构上先写「财聚」，再写「身不任」，两句不能合成一句。","pr":"找一张有三合或三会的盘，写出成立的三个条件各是什么，缺哪一条会降级成什么。","q":[{"question":"三合局成立的必备条件之一是什么？","options":["三支齐见","天干透出化神","月令同气"],"answer":"三支齐见","explanation":"三合须长生、帝旺、墓三支齐见；只见两支只能论半合。"},{"question":"「见合」与「成局」的区别在于？","options":["没有区别","是否满足三支齐见、月令不逆、无强冲破"],"answer":"是否满足三支齐见、月令不逆、无强冲破","explanation":"见合只是形式，成局要看三个条件是否同时满足，否则力量不成立。"}]},{"id":"L54","b":"六冲是六组正面对撞：子午、丑未、寅申、卯酉、辰戌、巳亥。冲的实质是藏干互伤，不是两个字打架。","h":"冲要看落在哪一宫、伤的是谁","p":["六冲的配对是固定的：子午冲（水火）、丑未冲（土土）、寅申冲（木金）、卯酉冲（木金）、辰戌冲（土土）、巳亥冲（水火）。土土相冲最特殊，冲开的是墓库。","冲的力度取决于位置：年月冲多在早年与长辈，月日冲动家庭与配偶宫，日时冲动子女与晚景。同一组冲落在不同宫，事应完全不同。","冲有解：逢合可解冲（如子午冲遇丑来合子），逢冲也可破合。判断顺序是先看有没有合来解，再看有没有第二个冲叠加。","冲不一定坏：身弱而冲去忌神、墓库被冲开取用，都是好事。写「冲」的时候必须同时写「冲掉了什么」，否则等于没写。"],"s":["列出六冲配对，标出盘中命中哪几组。","标出每组冲落在哪两宫。","检查是否有合来解冲。","写明冲掉的是喜神还是忌神。"],"e":"戊午 甲子 乙卯 乙酉：子午冲（年月）与卯酉冲（日时）同时存在，四正全见。两组冲一上一下，分别动根基与夫妻、子女两宫；此时不能笼统说「冲多不好」，要分宫写，并看两冲是否互相牵制。","pr":"找一张有两个冲的盘，分别写出冲的宫位、被冲掉的藏干、有无合解，最后判断是损是益。","q":[{"question":"六冲中属于「土土相冲、冲开墓库」的是？","options":["子午","辰戌","寅申"],"answer":"辰戌","explanation":"辰戌皆为土，相冲的效果是冲开墓库，与其他五组不同。"},{"question":"判断一次冲是好是坏，必须先弄清什么？","options":["冲的字有几个","冲掉的是喜神还是忌神","冲在哪个季节"],"answer":"冲掉的是喜神还是忌神","explanation":"冲只是力量动作，损益取决于被冲掉的是喜是忌，以及落在哪一宫。"}]},{"id":"L55","b":"刑、自刑、害、破，是四组比冲合更细的关系。它们的成立条件各家最不统一，所以最需要标口径。","h":"先定成立条件，再谈含义","p":["三刑：寅巳申、丑戌未，须三支齐见才算成立；缺一支只论冲或暗损，不硬凑成刑。相刑：子卯。自刑：辰辰、午午、酉酉、亥亥，须同支并见。","六害：子未、丑午、寅巳、卯辰、申亥、酉戌。害的力度小于冲，多主暗中的损耗与不合，不能单独断事。","六破：子酉、卯午、辰丑、未戌、寅亥、巳申。破的含义各家分歧最大，有的只作轻微破损论，有的并入冲看。本页只标位置。","使用原则：刑害破只能作提示，不能作结论。要写就必须同时写「落在哪一宫、有无合解、有无第二个关系叠加」，缺一项就不要写。"],"s":["列出盘中所有刑、害、破。","检查成立条件：三支是否齐见、是否同支并见。","标出落宫与有无合解。","只写提示，不写事件断言。"],"e":"丁丑 辛亥 丁丑 丁未：两个丑夹一未，丑未相冲成立；丑戌未三刑因缺戌而不成立。这一盘正好用来练「什么算成立」——冲成立、刑不成立，两者不能混为一谈。","pr":"找一张有刑或害的盘，先写成立条件是否满足，再写它落在哪一宫；写不出条件就不要写结论。","q":[{"question":"丑戌未三刑，只有丑、未两支时如何论？","options":["仍算三刑","不论三刑，只论丑未相冲"],"answer":"不论三刑，只论丑未相冲","explanation":"三刑须三支齐见，缺戌则条件不成立，此时丑未之间是六冲关系。"},{"question":"刑害破在报告里应当怎么用？","options":["直接断事件","只作提示，须同写宫位与合解"],"answer":"只作提示，须同写宫位与合解","explanation":"这四组关系争议最大，只能作提示；不写宫位与合解就无法核对。"}]},{"id":"L13","b":"透干是露在外面，通根是扎在下面。天干再漂亮，地支没有同类就是虚的——这是判旺衰最实用的一条。","h":"透与根，两件事分开看","p":["透干：天干上出现该五行。透出的力量直接、公开、易被看见，但透而不通根，只是「有名无实」。","通根：地支藏干里有同类。根分三档：坐支本气最实，月支本气次之（但月令本身权重最高），年时支或余气最弱。","透而不通根叫虚透：名声在外而实力不足，遇克即倒。通根而不透叫暗藏：有力而不外显，遇引动才发。两种都要写清。","常见错误：把「天干有两个甲」当成木旺。天干再多，地支无根也只是浮木；反过来，地支有根而天干不透，力量反而更耐用。"],"s":["标出每个天干是否透出。","逐个查地支藏干，判有无同类。","给根分档：坐支、月支、余气。","写出「虚透」或「暗藏」的结论。"],"e":"乙卯 戊子 甲寅 甲子：甲木日主，坐寅（藏甲）为本气之根，年支卯为木之旺地，时干又透一甲——透而且通根，属身强。对照甲坐申：申藏庚壬戊无甲，虽透而无根，力量完全不同。","pr":"取三个天干，分别判断是「透而通根」「透而不通根」「通根而不透」，各举一盘为证。","q":[{"question":"天干透出但地支无同类，称为什么？","options":["虚透","暗藏","通根"],"answer":"虚透","explanation":"透而无根为虚透，力量浮而不实。"},{"question":"判断通根强弱，最实的一种是？","options":["年支余气","坐支本气","时支中气"],"answer":"坐支本气","explanation":"日主坐支本气为最实的根，年时支与余气力量递减。"}]},{"id":"L17","b":"合是牵住，化是变成。见合不等于化，化要有条件：月令支持、化神有根、无破。三条缺一条，只能写「合而不化」。","h":"合与化，条件差三步","p":["天干五合：甲己合土、乙庚合金、丙辛合水、丁壬合木、戊癸合火。合只表示两者相牵，日主与另一个字被绑在一起，力量被分走一部分。","化的三个条件：月令是化神当令、化神在天干或地支有根、没有强冲来破。三条同时满足才叫化气，否则一律写「合而不化」。","合而不化的实际影响：两字互相牵制，各自力量都打折。比如甲己合，甲木被牵住，克土之力减弱；己土也被牵住，生金之力减弱。","化气成立的影响更大：日主性质可能改变（见「从格、化气格」一讲），此时整个十神体系要重排。这一步不能凭感觉，必须逐条核对三个条件。"],"s":["找出天干五合的组合。","查月令是否为化神当令。","查化神有无根。","查有无冲来破，三条齐了才写「化」。"],"e":"乙丑 庚辰 甲戌 辛未：乙庚相邻为合，化神为金。辰月土旺生金、支中丑未戌皆土、又见辛金透出，化神有根有势，月令不逆，此时可讨论「乙庚化金」。若换成寅月，木旺当令，金无根，就只能写「合而不化」。","pr":"找一组天干相合，逐条核对三个条件，写出结论是「化」还是「合而不化」，并说明缺哪一条。","q":[{"question":"见天干相合，能否直接判为「化」？","options":["能","不能，须核月令、化神之根、有无冲破"],"answer":"不能，须核月令、化神之根、有无冲破","explanation":"合是牵制，化是质变，三条条件缺一即只能论合而不化。"},{"question":"「合而不化」的主要影响是？","options":["两字力量都打折","两者完全消失","日主性质改变"],"answer":"两字力量都打折","explanation":"合而不化时双方互相牵制，各自力量减弱，但不改变五行属性。"}]},{"id":"L18","b":"同一个冲，落在年柱和落在时柱，是两件事。全局语境就是把「关系」放回「宫位」和「力量」里去看。","h":"三问定位：哪两宫、伤什么、有无解","p":["第一问哪两宫：年月为根基与长辈，月日为家庭与配偶，日时为子女与晚景。冲合刑害落在哪两柱，直接决定它谈的是哪一层。","第二问伤什么：冲要看藏干谁受伤。寅申冲，寅中甲丙戊、申中庚壬戊，木火与金水互伤，具体伤哪一位要看谁有根。","第三问有无解：逢合可解，逢第二个冲可加剧，逢岁运再来同组关系则叠加。三步走完，才谈得上损益。","全局还要看数量：一冲一合同时存在时，先论合还是先论冲，各家不一。本页的口径是先合后冲——合能牵住，冲才谈得上被分力。"],"s":["标出每组关系的两宫位置。","拆开藏干，判谁受伤。","检查有无合解、有无第二重关系。","按「先合后冲」的口径写结论。"],"e":"丁丑 辛亥 丁丑 丁未：丑未冲落在年日、月日之间，伤的是丑中癸水与未中丁乙；两丑夹一未，冲力集中在中宫（日支），故读作家庭与自身的反复，而不是笼统的「六亲有损」。","pr":"取一张有两组以上关系的盘，按三问逐条写，最后给出「损在哪一宫」的一句话结论。","q":[{"question":"判断一次冲的影响，第一问应当问什么？","options":["冲的力量有多大","冲落在哪两宫","冲的字好不好"],"answer":"冲落在哪两宫","explanation":"宫位决定所谈的层次，先定位再谈力量与损益。"},{"question":"本页对「一冲一合同时出现」的处理口径是？","options":["先冲后合","先合后冲"],"answer":"先合后冲","explanation":"合能牵住，冲的力量才谈得上被分走，故先论合。"}]},{"id":"L14","b":"旺衰不是数五行个数。五个木不一定旺，两个土不一定弱——因为位置、月令、藏干让每一个字的分量都不同。","h":"为什么计数法会失效","p":["位置不同：月令一个字抵得上其他位置的两个到三个。同样是木，生在寅月和生在酉月，力量差一个量级。","透藏不同：天干透出的字公开而直接，地支藏干里的字要看是否透出、是第几层气。数「八字里有几个木」会把余气与当令本气等同，这是最常见的错。","生扶不同：比劫是同类，印是生我，两者的作用都是帮，但性质不同。身弱见印比是帮，身旺见印比是滞。同一组字，强弱不同结论相反。","正确做法是分栏：先写「得令」、再写「得地」、再写「得势」，最后一栏列「克泄耗」。四栏各自独立成句，最后合起来判强弱。跳过任何一栏，判断都会飘。"],"s":["写月令本气与日主的关系，定得令或失令。","查四支藏干，定通根有无与强弱。","数明干中的印比，定得势。","列克泄耗（官杀、食伤、财）各自的分量。"],"e":"己未 己巳 辛丑 戊子：土有五处，若按个数算「土极旺」；但辛金坐丑（藏己辛癸）有根、月令巳中丙火当令克金，实际是「印重身不弱而受制」。分栏一写，结论立刻与计数法不同——这就是为什么要分栏。","pr":"取一张五行分布明显不均的盘，先用计数法写一句结论，再用四栏法写一遍，比较两者差异并说明哪个可信。","q":[{"question":"为什么不能用五行个数判断旺衰？","options":["因为个数总是数错","因为月令、位置、透藏让每个字分量不同"],"answer":"因为月令、位置、透藏让每个字分量不同","explanation":"同样一个字，在月令与在余气、透干与藏支，力量差很多，个数量化不了这种差别。"},{"question":"判旺衰时，「得势」看的是？","options":["地支藏干","明干中的印与比劫","月令本气"],"answer":"明干中的印与比劫","explanation":"得势指明面上有几个生我或同我的天干，藏干不重复计。"}]},{"id":"L56","b":"旺衰要写成四栏，不是写一句「身弱」。四栏是得令、得地、得势、克泄耗——前三栏加分，第四栏扣分，每一栏都要有可核对的证据。","h":"四栏怎么写才算合格","p":["第一栏得令：写月支是什么、本气是什么、与日主什么关系。若本气是比劫或印，记「得令」；若本气是官杀食伤财，记「失令」。这一栏权重最高（本页模型 40 分）。","第二栏得地：逐个查四支藏干，看有没有日主同五行。坐支本气最实，月支次之，年时支与余气再次。写清「通了几处、最实的一处在哪」。本页模型 35 分。","第三栏得势：数明干里的印与比劫，各几个、有无被合被克。这一栏最容易虚高，因为暗藏的印比不能再算一次。本页模型 25 分。","第四栏克泄耗：官杀（克）、食伤（泄）、财（耗）各占多少，有没有成局。前三栏讲「我有多强」，这一栏讲「我要扛多少」。四栏合起来才叫旺衰判断。"],"s":["写月支本气与日主关系。","逐支查藏干，记通根处数与最实一处。","数明干印比，扣除被合被克者。","列官杀、食伤、财的分量与成局情况。"],"e":"壬戌 庚戌 甲午 甲子（甲木日主）：得令——戌月本气戊土，为偏财，失令，12/40；得地——四支藏干无甲，通根 0，0/35；得势——年干壬偏印 +7、时干甲比肩 +8，15/25；克泄耗——土财 3.0、火食伤 1.9、金官杀 2.4。合计 27 分，判偏弱。四栏一写，「为什么偏弱」就不再是感觉。","pr":"取三张盘，各写一份四栏证据表，要求每一栏都能指出具体干支，不许出现「感觉」「看起来」。","q":[{"question":"本页模型的四栏权重是？","options":["月令40、通根35、天干帮扶25","各25","月令50、通根30、帮扶20"],"answer":"月令40、通根35、天干帮扶25","explanation":"这是本页自定的透明试算模型，合计 100，目的在让过程可复算，不是传统定论。"},{"question":"「得势」一栏最容易出现的错误是？","options":["漏数藏干","把暗藏的印比重复计入明干"],"answer":"把暗藏的印比重复计入明干","explanation":"得势只数明干，藏干已在得地一栏计过，重复计会虚高。"}]},{"id":"L57","b":"失令不一定弱，得令不一定旺。三张盘对读，就能看出「月令」只是四栏里的一栏，不是全部。","h":"三盘对读：把权重拆开看","p":["失令而不弱：月令是官杀或财，但日主坐支本气有根、天干又见印比，通根与得势补回来。这类盘常被误判成弱，实际能任。","得令而反弱：月令是比劫，看似得令，但地支被冲、天干被合，或全局克泄耗成片。此时「得令」是虚的，要看实际能用的力量。","还有一种：得令得地而印比同旺，气多而无出口。这种不叫「强」，叫「旺而无用」——旺是气多，强是能用，两者要分开说。","对读方法：把三张盘的四栏并列写成一张表，逐栏比较，找出「哪一栏把结论翻转了」。这一步做熟，判旺衰就不再靠印象。"],"s":["选三张盘：一张失令不弱、一张得令反弱、一张旺而无用。","逐栏写分数与证据。","找出决定结论的那一栏。","用一句话说明「为什么不是相反结论」。"],"e":"对照三盘：TC03（戌月甲木，失令且无根，27 分偏弱）；TC13（子月壬水坐子，得令得地，78 分偏强）；TC17（申月庚金坐申，68 分偏强而食伤 3.5，属旺而有出口）。三张盘并排，就能看出「得令」在不同盘里的权重完全不同。","pr":"找一张「失令但不弱」的盘，写出是哪一栏把结论翻转了；再找一张「得令但不旺」的，同样写。","q":[{"question":"失令的盘一定偏弱吗？","options":["一定","不一定，通根与得势可以补回来"],"answer":"不一定，通根与得势可以补回来","explanation":"月令只是四栏之一，坐支有根、天干有印比时，失令仍可不弱。"},{"question":"「旺」与「强」的区别是？","options":["没有区别","旺是气多，强是能用"],"answer":"旺是气多，强是能用","explanation":"气多而无出口叫旺而无用，能承能发才叫强。"}]},{"id":"L60","b":"这一讲不教新知识，只练一件事：拿到陌生盘，能不能在十分钟内写出四栏、给出强弱、并说清哪一栏最不确定。","h":"限时四栏实训","p":["流程固定：先定盘（时间口径与四柱），再写四栏，再判强弱，最后写一句「我最不确定的是哪一栏、为什么」。顺序不许跳。","四栏写完再做交叉检查：得令与得地是否矛盾、得势有没有被合、克泄耗有没有成局。矛盾之处往往就是判错的地方。","判强弱只给三档：偏强、中和、偏弱。不要写「身弱偏中和」这种模棱话——模棱话在实战里等于没判，因为后面取用神时无从下手。","最后写不确定性：哪一栏证据最薄、哪一栏依赖了口述精度。合格的作业一定有一句「若某支藏干被冲，结论会翻转」。"],"s":["限时 10 分钟完成一盘的定盘。","四栏逐条写证据，各带干支。","给三档结论，不许写模棱话。","写一句最不确定处与翻转条件。"],"e":"以 TC15 为例：戊土生亥月失令（财当令），日支申藏戊为根，时支巳藏丙戊为根——得地有两处；天干两癸为财、丁火为印，得势仅印一点；克泄耗中财 4.2、食伤 2.7 成流。合计 26 分偏弱。最不确定处：巳中戊土是否被亥冲，若被冲则根减，结论更弱。","pr":"连做五张陌生盘，每张 10 分钟，四栏齐全；做完把五张里「最不确定的一栏」统计一遍，看自己常卡在哪。","q":[{"question":"旺衰结论应当给几档？","options":["越多档越准","偏强、中和、偏弱三档"],"answer":"偏强、中和、偏弱三档","explanation":"档位太多会让取用神时无从下手，三档足够支撑后续判断。"},{"question":"一份合格的旺衰作业必须包含什么？","options":["只写结论","结论加最不确定处与翻转条件"],"answer":"结论加最不确定处与翻转条件","explanation":"写不出翻转条件，说明四栏只是走过场，没有真正比较过力量。"}]},{"id":"L15","b":"格局不是给命盘起个名字，是回答「这个盘靠什么成立」。取格的入口是月令，但出口是条件。","h":"从月令取格，用条件校验","p":["取格第一步看月令本气。本气透干，以本气取格；本气不透，取月支所藏且透出天干的中气或余气。都不透时，按本气论但要注明「不透」。","第二步看格是否有护：官格要有财生、有印护；财格要有食伤生、有比劫卫；食伤格要有印制或财泄。缺护的格叫「格成而无护」，成色打折。","第三步写破坏条件：官格怕伤官见官，财格怕比劫夺财，印格怕财破印。破坏条件写在纸上的意义，是让你在流年出现时能提前指出风险，而不是事后解释。","格局只写「结构」，不写「贵贱」。同一格在不同行业、不同时代兑现完全不同。把格名当结论，是初学者最普遍的越界。"],"s":["看月令本气，查是否透干。","本气不透则取透出之中余气。","写该格的护与破各一条。","注明此格成立所依赖的条件。"],"e":"戊辰 庚申 己未 丙寅：己土生申月，申中庚金透于月干，本气透出，取伤官格。护：时干丙火正印可制伤；破：财旺则坏印。故写作「伤官格，印制伤为护，财破印为破，成色取决于印是否能立住」。","pr":"取一张盘，写出主格与备选格各一，并各写一条护、一条破；说明你为什么把主格放在前面。","q":[{"question":"月令本气不透时，取格的规则是？","options":["直接按本气论，不必注明","取月支所藏且透出天干的中气或余气"],"answer":"取月支所藏且透出天干的中气或余气","explanation":"本气不透则格随透出之气走，但必须注明本气未透，以免读者误判。"},{"question":"格局名称能否直接当作贵贱结论？","options":["能，格高则贵","不能，格只描述结构"],"answer":"不能，格只描述结构","explanation":"同一格在不同行业与时代兑现差别极大，格名只说明结构成立方式。"}]},{"id":"L59","b":"十神之间是有路线的：谁生谁、谁克谁、谁救谁。看清路线，才知道一个盘的力量往哪里走。","h":"画三条线：生、克、救","p":["生线：印生比劫、比劫生食伤、食伤生财、财生官杀、官杀生印。这条线走通，叫「流通」；某一环断掉，力量就堵在那里。","克线：官杀克比劫、比劫克财、财克印、印克食伤、食伤克官杀。克线的意义是「约束」，不是「伤害」；要看被克的一方有没有救。","救应：官杀太旺，用印化（官生印、印生身）；财太旺，用比劫分担；食伤太旺，用印制；印太旺，用财破。救应的判断标准是「救神有没有根」。","写组合时按「主线—阻隔—救应」三段写。比如「伤官生财为主线，财旺坏印为阻隔，印被坏则贵气减」，一句话就说清了全局。"],"s":["标出日主与各十神的位置。","画出实际的生线与克线。","找出断点与阻隔。","指出救神及其是否有根。"],"e":"戊辰 庚申 己未 丙寅：主线是伤官（庚）生财（申中壬）、财又生官（寅中甲）；阻隔是财旺克印（丙），救应是丙火坐寅有根、未被合。故结论写成「伤官生财为主，印为救而根在寅，救得住则格不破」。","pr":"给一张盘画三条线，标出断点在哪；再说明如果断点被流年补上，结构会怎么变。","q":[{"question":"「救应」成立的关键是？","options":["救神名字对","救神有根且未被合克"],"answer":"救神有根且未被合克","explanation":"有名无根之救等于没有，救神必须能实际发挥作用。"},{"question":"伤官生财的路线，中间若财坏印，会怎样？","options":["格更清","贵气减，需另寻救应"],"answer":"贵气减，需另寻救应","explanation":"印被财坏则制伤之力消失，伤官无制，结构成色下降。"}]},{"id":"L19","b":"官杀与食伤，是「压力」与「输出」两端。看结构先看这两端有没有形成闭环：压力有没有出口，输出有没有约束。","h":"压力与输出，各看三点","p":["官杀看三点：是否混杂（正官七杀同时透）、是否有制（食伤制杀）、是否有化（印化官杀）。混杂而无制无化，压力就会变成内耗。","食伤看三点：是否过旺（泄身太过）、是否有制（印）、是否有财可泄（食伤生财）。过旺无制，输出就会失控；有财可泄，输出才有落点。","组合读法：官杀旺而食伤制之，叫「制杀」；官杀旺而印化之，叫「化杀」。两者都能解压力，但路径不同——制是正面对抗，化是转成资源。","要写的结论是「压力从哪来、出口在哪、够不够」。写不出出口，就不要写「压力大」；那只是一种形容，不是判断。"],"s":["标出官杀的位置与是否混杂。","标出食伤的位置与旺度。","判是「制」还是「化」，或两者皆无。","写压力的来源与出口。"],"e":"乙丑 庚辰 甲戌 辛未：庚为七杀透月干、辛为正官透时干，官杀混杂；印仅 0.9、食伤 0.8，既无制也无化。结构上写作「官杀混杂而身弱，压力无处转圜，先取印化、次取比劫帮身」。","pr":"找一张官杀旺的盘，写出「制」与「化」两条可能路径，并说明哪条在本盘更有条件。","q":[{"question":"官杀混杂且无制无化，主要问题是什么？","options":["压力无处转化","一定破财","一定无子"],"answer":"压力无处转化","explanation":"混杂本身不是灾难，问题在于缺少制或化的出口，压力只能内耗。"},{"question":"「制杀」与「化杀」的区别是？","options":["没有区别","制是正面对抗，化是转成资源"],"answer":"制是正面对抗，化是转成资源","explanation":"食伤制杀是压制，印化杀是把压力转成庇护与资源，路径不同。"}]},{"id":"L20","b":"财与印比，是「所得」与「所守」。财旺看身能不能任，印重看财能不能通——这一讲把两组最容易失衡的结构摆在一起。","h":"所得与所守，先看失衡在哪端","p":["财旺身弱：机会多、摊子大，自身承接不足。取印比帮身，见比劫分财、见印化食伤生身；忌再行财地。断语只能写「得与守之间有落差」，不能写「必穷」。","印重身旺：庇护多、自身气足，但出口少。取食伤泄秀、财耗其势；忌再见印比。这类盘常见「条件好而动力弱」，但这是倾向不是定论。","财印相战：财克印。若印为用而财旺，则贵气受损；若财为用而印重，则财路被堵。判断关键是「谁是救神、谁有根」。","比劫夺财：财透而比劫成群。此时争的是分配，不是有无。要写「有分夺之势」，不要说「必被人骗」——后者既不可证伪，也容易误导。"],"s":["判财星旺度与日主强弱。","判印星旺度与有无出口。","查财印是否相战、比劫是否夺财。","写失衡在哪端、救神是什么。"],"e":"庚午 辛巳 丁酉 乙巳：丁火生巳月身强（71 分），偏财 2.4、正财 2.2、劫财 2.4，比劫与财几乎等量。结构写作「比劫争财，取官杀制劫、食伤通关生财；财有根，故为分配问题而非匮乏」。","pr":"取一张财旺或印重的盘，写出失衡的那一端与救神，再写一句「这个结构不能被推成什么」。","q":[{"question":"财旺身弱的取用方向是？","options":["再行财地","取印比帮身"],"answer":"取印比帮身","explanation":"身不任财时，先补承接力；再行财地只会加重负担。"},{"question":"比劫夺财最稳妥的表述是？","options":["必被人骗财","有分夺之势，属分配问题"],"answer":"有分夺之势，属分配问题","explanation":"结构只能说明有分夺的条件，是否真的破财要看运年与现实，不能断言。"}]},{"id":"L42","b":"格局进阶只做一件事：把「成格」写成条件矩阵。哪几条满足、哪几条不满足，一目了然，才谈得上成色。","h":"成格、破格、救应三张表","p":["成格条件：格神有根、有护、不被冲合破坏。三条全满足为「格清」，缺一条为「格有瑕」，缺两条以上只能写作「有格之形」。","破格条件：格神被冲、被合走、被克破。破格不等于命差，很多盘是「先破后成」——逢运补起救神，格又能立。","救应条件：破格处有没有救神、救神有没有根、救神会不会被第二个力量再破。三条决定「能不能救回来」。","写法：列一张三行表——成格条件、当前是否满足、破格风险。这张表就是格局判断的全部，不必写形容词。"],"s":["写下格神与格名。","列三条成格条件，逐条打勾或打叉。","列两条破格风险。","写救神与救神的根。"],"e":"戊辰 庚申 己未 丙寅（伤官格）：成格条件①伤官有根（申本气庚）✓；②有印制伤（丙在时干）✓；③印不被财坏（财 1.5，未成局）✓。三条全满足，写作「格清而印为关键，财旺之年印受伤即为破格之始」。","pr":"取一张盘，写出成格三条件是否满足，并指出「哪一年会破格」，给出具体条件而不是年份猜测。","q":[{"question":"判断「格清」的标准是？","options":["格名好听","格神有根、有护、不被破坏，三条齐备"],"answer":"格神有根、有护、不被破坏，三条齐备","explanation":"成格是条件判断，不是名目判断，三条缺一即为有瑕。"},{"question":"破格是否等于命差？","options":["是","不是，逢运补起救神可以复立"],"answer":"不是，逢运补起救神可以复立","explanation":"破格描述结构被破坏，运来救应仍可恢复，不能直接推成结果。"}]},{"id":"L43","b":"从格与化气格是最容易误判的两类，因为它们都要求「日主几乎无立足之地」。所以这一讲先教怎么否证，而不是怎么成立。","h":"先证否，再论从","p":["从格的三条硬条件：日主无根（四支藏干无同类）、无强印生扶、主导之气成片（占全局七成以上）。三条缺一条，一律作常格论。","常见误判：看到日主分数低就断从。分数低只说明帮身少，不等于没有根——一个藏干余气就足以否掉从格。所以第一步永远是逐支查藏干。","化气格的条件更严：日主与相邻天干五合、月令为化神当令、化神有根、无冲破。四条齐备才谈化气，缺一条仍是常格。","判错的代价很大：从格取用与常格相反。常格身弱要帮，从格身弱不能再帮——帮了反而破格。所以这一步必须写出否证条件，写不出就不许下结论。"],"s":["逐支查藏干，确认日主是否真的无根。","查印星有无透干、有无根。","算主导之气的占比。","写下「若某条成立则不从此格」的否证条件。"],"e":"辛酉 庚寅 戊寅 辛酉（从儿候选）：伤官 4.0、日主 15 分、印 1.3。否证检查：寅中藏丙戊，戊为日主同类之余气——有此一根，严格说不能论纯从，只能写「近从儿，然寅中戊土为根，逢土运即回常格」。","pr":"取一张极弱的盘，先写三条否证条件逐条核对，再决定是否下从格结论；写出「什么情况下你的结论会被推翻」。","q":[{"question":"判断从格的第一步应当是？","options":["看日主分数低不低","逐支查藏干确认是否真的无根"],"answer":"逐支查藏干确认是否真的无根","explanation":"分数低不等于无根，一个余气就能否掉从格，必须先查藏干。"},{"question":"从格与常格的取用方向？","options":["相同","相反，从格不宜再帮身"],"answer":"相反，从格不宜再帮身","explanation":"从格顺主导之气，帮身反而破格；这一步判错，整盘反读。"}]},{"id":"L16","b":"「用神」这个词至少在三种语境里出现：调候、扶抑、通关。三种问的不是同一个问题，答案可以相反。","h":"三种语境，三个问题","p":["调候问的是「这个盘冷不冷、燥不燥」。冬木要火暖，夏金要水润，与身强身弱无关。一个身强的冬木照样可能需要火。","扶抑问的是「日主扛不扛得住」。身弱取印比，身旺取食伤财官。这一层依赖旺衰四栏的结论。","通关问的是「两强相持，谁来当中介」。金木相战用水中介，水火相战用木中介。条件是两方都强、中介在局中有根。","三种结论冲突时，正确做法是并列写，不合并。写「调候取火、扶抑取水，两者相反；本盘冬水寒，调候优先，但火若无根则只能取水通关」——这样写，读的人才看得懂你在权衡什么。"],"s":["判寒暖燥湿，写调候所需。","判旺衰，写扶抑所取。","查两强相持，写通关中介。","三条并列，标明优先顺序与理由。"],"e":"乙卯 戊子 甲寅 甲子（冬木）：调候要火（冬水寒，木不发荣）；扶抑看身强（印比 6.6），该取食伤财；通关看水木之间无须中介。三条合写为「调候取火为先，扶抑取火土为次，二者同向」，这一盘恰好不冲突——冲突的盘才是常态。","pr":"找一张调候与扶抑方向相反的盘，把两条结论并列写出，并说明你优先哪一条、为什么。","q":[{"question":"调候取用与身强身弱的关系是？","options":["完全由身强弱决定","相对独立，寒暖燥湿另有标准"],"answer":"相对独立，寒暖燥湿另有标准","explanation":"冬木身强仍可能要火，调候看季节与燥湿，不看分数。"},{"question":"三种取用结论冲突时应当？","options":["选一个最好听的","并列写，标明优先与理由"],"answer":"并列写，标明优先与理由","explanation":"合并成一句会掩盖权衡过程，读者无法复核你的取舍。"}]},{"id":"L58","b":"扶抑、调候、格局、用神这四个词经常被混用。分工清楚，取用才不会自相矛盾。","h":"四个词，四种职能","p":["扶抑是方法：身弱帮、身旺泄，依据是旺衰四栏。它回答「力量够不够」。","调候是另一套方法：看寒暖燥湿，依据是月令与季节。它回答「环境舒不舒服」，与力量无关。","格局是结构判断：格神有没有根、有没有护、会不会破。它回答「这个盘靠什么成立」。","用神是结论：在上述三者权衡后，指出「最需要的那一个字」。所以用神必须带条件——「取丙火为用，条件是丙不被癸合」。没有条件的用神，等于没有。"],"s":["先写扶抑方向。","再写调候所需。","再写格局护破。","合成一句带条件的用神结论。"],"e":"己未 己巳 辛丑 戊子：扶抑——印 5.8 太重，宜泄不宜再生，取水木；调候——巳月燥，需水润；格局——印重而身不弱，属「印格身旺」，破在财。三条同指水木，故用神写作「取壬癸水为用，条件是水不被戊己合住；木为佐」。","pr":"取一张盘，分别写扶抑、调候、格局三句，再合成一句带条件的用神；若三者冲突，写明你优先哪一条。","q":[{"question":"「用神」与「格局」的关系是？","options":["同一个概念","格局是结构判断，用神是权衡后的结论"],"answer":"格局是结构判断，用神是权衡后的结论","explanation":"格局说盘靠什么成立，用神说最需要哪个字，层次不同。"},{"question":"一个合格的用神结论必须包含什么？","options":["只写一个字","字加成立条件"],"answer":"字加成立条件","explanation":"无条件之用神无法核对，也无法在流年中判断何时被破坏。"}]},{"id":"L21","b":"调候查的不是神煞，是寒暖燥湿。它问的是「这个季节出生的人，环境缺什么」，答案常常与旺衰无关。","h":"四时与燥湿，两步查","p":["第一步定季节：寅卯辰春（木旺、渐暖）、巳午未夏（火旺、燥）、申酉戌秋（金旺、渐凉）、亥子丑冬（水旺、寒）。季节决定大方向。","第二步定燥湿：夏未必都燥（有水则润），冬未必都寒（有火则暖）。要看局中水火的实数，而不是只看月令。比如巳月见两子一壬，燥气已被解掉大半。","调候的判断标准很朴素：冬生而火不足，写「需暖」；夏生而水不足，写「需润」；四季土重而木不足，写「需疏」。三类都不涉吉凶。","必须写清边界：本页给的是原则判断，不是《穷通宝鉴》逐条调候表。那一百二十条各家版本互有出入，没有校本之前不宜照抄。"],"s":["定季节与当令五行。","数局中水火实数。","判是寒、暖、燥、湿哪一端偏。","写所需与所需之字是否有根。"],"e":"己未 己巳 辛丑 戊子：巳月属夏，本应燥；但支中有子水、丑中癸水，火仅丙一点，实际是「燥而未烈」。调候写作「需水润土洗金，水已有根（子），不必再补，反忌土增」。","pr":"取一张夏月或冬月的盘，先按季节写一句，再按水火实数修正一句，比较两句是否相同。","q":[{"question":"调候判断的核心是什么？","options":["寒暖燥湿","身强身弱","神煞吉凶"],"answer":"寒暖燥湿","explanation":"调候看季节与局中水火实数，与旺衰、神煞是不同层面。"},{"question":"本页的调候结论属于？","options":["《穷通宝鉴》逐条照录","原则判断，非逐条表"],"answer":"原则判断，非逐条表","explanation":"一百二十条各家版本有出入，本页只给原则，避免以讹传讹。"}]},{"id":"L22","b":"起运不是「几岁起」，是一个具体的公历日期。算不出日期，后面所有「哪一年」都是猜的。","h":"顺逆看年干，时间差折年岁","p":["顺逆只看两件事：年干阴阳与性别。阳男、阴女顺行；阴男、阳女逆行。这里用的是年干，不是日干，弄错方向整排大运全反。","顺行数到下一个节，逆行数到上一个节。出生到该节的时间差，就是起运的依据：三天折一年，一天折四月，一时辰折十天。本页按分钟折算，4320 分折一年、360 分折一月、12 分折一日。","起运日期 = 出生时刻 + 折算出的年月日时。交运之后每十年换一步，大运干支从月柱开始顺推或逆推一位。","必须注意：交运年可能横跨两步大运。公历年份只是近似，真正的换运时刻要按交运日期算；写「2023 年进癸丑运」是错的，要写「2023 年 3 月 16 日交癸丑运」。"],"s":["看年干阴阳与性别，定顺逆。","顺数下一节、逆数上一节，取时间差。","按三日一年折算年月日时。","出生时刻加折算值，得交运日期。"],"e":"壬戌 庚戌 甲午 甲子，乾造，年干壬为阳、男命顺行。生于 1982-11-07 00:20，下一节为立冬，相距约 1544 分钟，折 0 年 4 月 8 日 16 时，交运在 1983 年 3 月中旬。第一步大运从月柱庚戌顺推一位为辛亥，故 1983—1993 走辛亥。","pr":"取一张盘，手算顺逆与交运日期，再与网页对照；把「交运日期」精确到日写出来。","q":[{"question":"起运顺逆由什么决定？","options":["日干阴阳与性别","年干阴阳与性别"],"answer":"年干阴阳与性别","explanation":"阳男阴女顺行、阴男阳女逆行，依据是年干而非日干。"},{"question":"三天折合多长时间的大运？","options":["一年","一个月","十天"],"answer":"一年","explanation":"三日折一年，一日折四月，一时辰折十天，这是起运折算的基本比例。"}]},{"id":"L32","b":"同一张盘，男命与女命的起运方向可能相反。四种组合各推一遍，手上有数，就不会在实战里凭印象。","h":"四种组合的手推流程","p":["阳年干（甲丙戊庚壬）：男顺女逆。阴年干（乙丁己辛癸）：男逆女顺。记法只有八个字：阳男阴女顺，阴男阳女逆。","顺行从月柱往下一位推，逆行从月柱往上一位推。月柱是甲午，顺推为乙未、丙申；逆推为癸巳、壬辰。","起运岁数两性算法相同，都数到相应的节，差别只在「数下一个」还是「数上一个」。所以同一天出生的男女，交运日期可能差得很远。","写法：先写方向，再写交运日期，再列前五步大运干支。三步写完，别人才能复核你排得对不对。"],"s":["写年干，判阴阳。","配性别，定顺逆。","定所数之节，算时间差。","列前五步大运干支与交运年。"],"e":"同一组四柱 壬戌 庚戌 甲午 甲子：乾造顺行，第一步辛亥，1983 年交；若为坤造则逆行，第一步己酉，同样数到立冬但方向相反，前五步为己酉、戊申、丁未、丙午、乙巳。两张盘的年月日时完全相同，运程方向整列相反。","pr":"任取一张盘，分别以乾造、坤造排一次大运，写出前五步与交运年，比较差异。","q":[{"question":"阴年干女命的起运方向是？","options":["顺行","逆行"],"answer":"顺行","explanation":"阳男阴女顺、阴男阳女逆：本年干为阴、命主为女，属「阴女」，故顺行。"},{"question":"同四柱的乾造与坤造，大运方向？","options":["相同","可能相反"],"answer":"可能相反","explanation":"顺逆由年干阴阳配性别决定，性别一变方向可能整列翻转。"}]},{"id":"L31","b":"男女命的差别不在十神算法，而在「取哪一个星代表什么」。算法共通，取象有别，这一讲把两者摆在一张表上。","h":"共通的三层，差异的一层","p":["共通第一层：四柱、藏干、十神、旺衰的算法完全相同。性别参数不会改变十神映射，只影响起运顺逆与部分取象。","共通第二层：格局、用神、运年的判断方法相同。同一张盘换个性别，结构判断不变，变的只是「这个结构落在谁身上」。","差异层在取象：传统男命以财为妻星、以官杀为子女星；女命以官杀为夫星、以食伤为子女星。这是象的分配，不是算法的差异。","现代用法要加一层克制：星与宫必须同指才谈得上。男命见财星多不等于妻多，还要看日支（夫妻宫）是否被引动；女命见官杀混杂也不等于婚姻复杂，要看夫宫与运年。"],"s":["先按共通层排盘、判旺衰、取格。","再按性别取星：男财女官。","查星与宫是否同指。","写差异，注明这是取象不是算法。"],"e":"乙丑 庚辰 甲戌 辛未：同一盘，男命读作「官杀混杂、压力无出口，子女星为官杀」；女命读作「夫星官杀混杂，先看能否取清，再看夫宫戌土是否被冲」。旺衰与格局两句完全相同，只有取象层不同。","pr":"取一张盘，分别写男命、女命两段解读，要求前两句（旺衰、格局）逐字相同，只在取象层不同。","q":[{"question":"性别参数会改变十神映射吗？","options":["会","不会，只影响起运顺逆与取象"],"answer":"不会，只影响起运顺逆与取象","explanation":"十神由日主与目标字的生克阴阳决定，与性别无关。"},{"question":"传统女命以什么为夫星？","options":["财星","官杀"],"answer":"官杀","explanation":"女命以官杀为夫星、食伤为子女星；男命以财为妻星、官杀为子女星。"}]},{"id":"L23","b":"流年是一年的背景，流月是这一年内的时间刻度。两者叠加，才能说清「哪个月」。","h":"年看十神，月看交节","p":["流年干支按立春切换，不按元旦。流年天干相对日主的十神，是这一年的「主题词」——但主题词只是入口，不是结论。","流月按十二节切换，月干由流年天干用五虎遁推出。所以同一农历月在不同流年，月柱干支完全不同。","交节时刻要精确：一个月柱的起点是交节那一分钟，不是初一。月建与农历月名常差一位——正月建寅（立春后）、二月建卯（惊蛰后）、三月建辰（清明后）。所以写「三月」时要落到「清明后」，只写农历三月并不够：遇到闰月，同一个农历月名会横跨两个节。","联动写法：流年给出主题（如「财星到位」），流月给出窗口（如「申月财星得地」）。只写流年不写流月，等于只说「今年」；只写流月不看流年，等于只见树木。"],"s":["定流年干支与十神。","用五虎遁推十二流月。","标出每个月的交节时刻。","把年主题与月窗口对应起来。"],"e":"2026 丙午年，日主辛：丙为正官，故 2026 主题为「官星到位」。五虎遁「丙辛必定寻庚起」，丙年寅月起庚寅，顺推至午月为甲午。若问「几月最紧」，要看官星在哪个流月得地——午月火旺，官星最实。","pr":"取一张盘，写出某一年的流年十神，再推十二流月干支，标出你认为最关键的两个月及理由。","q":[{"question":"流年干支按什么切换？","options":["元旦","立春"],"answer":"立春","explanation":"流年以立春为界，与公历年不同步。"},{"question":"流月月干由什么推出？","options":["流年天干用五虎遁","日干用五鼠遁"],"answer":"流年天干用五虎遁","explanation":"流月以年干起五虎遁，一年十二个月干由此确定。"}]},{"id":"L44","b":"岁运实战的核心是分层：原局决定「有没有」，大运决定「推没推上台面」，流年决定「哪一年扣扳机」。三层缺一层，断语就是空的。","h":"三层各写一句，不许合并","p":["第一层原局：这个结构在原局是否存在。比如「财星有根、比劫成群」，这是原局事实，与运无关。写不出这一层，后面的运年就是无源之水。","第二层大运：这十年有没有把这个结构推到台面。帮身运到，身弱得助；财地运到，财旺更旺。大运是背景，决定「这十年主要矛盾是什么」。","第三层流年：哪一年扣动扳机。流年与原局、大运产生冲合刑害，或补上关键一字，才构成「触发」。没有触发的年份，背景再强也只是背景。","写法模板：「原局有 X（证据），大运 Y 使之 Z（机制），流年 W 触发（关系）。若 W 年无此事，则说明 X 未成立或 Y 被冲。」最后一句是反证，必须写。"],"s":["写原局事实与证据。","写大运的推向与机制。","写流年的触发关系。","写反证：什么情况下这套推理不成立。"],"e":"庚午 辛巳 丁酉 乙巳：原局比劫 3.4、财 4.6，属争财结构；行壬午运（官杀透）制比劫，是「把争的力量压下去」；2026 丙午年，丙火比肩再透、午火冲子？——须查具体支。三层写清，才谈得上「哪一年容易出现分配争议」。","pr":"选一件当事人已知的事，按四句模板倒推三层，再检查你的反证是否真的可能发生。","q":[{"question":"大运在判断中起什么作用？","options":["决定具体哪一年","决定这十年的主要矛盾与背景"],"answer":"决定这十年的主要矛盾与背景","explanation":"大运是十年背景，具体触发要靠流年与原局、大运的关系。"},{"question":"一套岁运推理必须包含什么？","options":["只写结论年份","原局、大运、流年三层加反证"],"answer":"原局、大运、流年三层加反证","explanation":"缺任何一层都无法核对，反证则用于防止事后自圆其说。"}]},{"id":"L73","b":"八步大运总读，不是把每步运都写一遍，而是给每一步定一个「主要矛盾」，八步连起来看走势。","h":"每运八项，只写关键三项","p":["八项清单：干支十神、与原局的冲合、旺衰的变化、格局的护破、六亲宫位、健康象义、财务与事业、应期窗口。逐项过一遍，防止漏看。","但报告里只写关键三项：这一步运「帮还是耗」、动了哪一宫、有没有破格。其余五项作为自查，不必全部写进正文。","走势要看连续性：连续三步帮身，是长期上行；一步帮一步耗，是起伏。把八步的「帮耗」标成一条线，趋势立刻可见。","交运年要单独标：交运当年横跨两步运，判断要写「上半年属前运、下半年属后运」，不能笼统归入某一步。"],"s":["列八步干支与十神。","标每步帮或耗。","标每步动了哪一宫、有无破格。","把八步连成一条走势线。"],"e":"壬戌 庚戌 甲午 甲子（身弱）：辛亥（官印，帮力有限）、壬子（印）帮、癸丑（印财）半帮、甲寅（比）大帮、乙卯（劫）帮、丙辰（食财）耗、丁巳（伤财）耗、戊午（财伤）大耗。八步连看是「先扬后抑」，前四十年顺势，后段需守。","pr":"取一张盘，做一张八步表：干支、帮耗、动宫、破格风险，四列；再用一句话概括走势。","q":[{"question":"八步大运总读最关键的三项是？","options":["八项全写","帮耗、动宫、破格"],"answer":"帮耗、动宫、破格","explanation":"其余项目用于自查，正文写这三项即可支撑判断。"},{"question":"交运当年的判断应当？","options":["整年归入新运","按交运日期分段"],"answer":"按交运日期分段","explanation":"交运日之前属前一步运，之后属后一步，不能整年一刀切。"}]},{"id":"L74","b":"同一年可能同时是「立春换年」和「交运换运」的年份。两个边界一起过，判断才不错位。","h":"两个边界取交集","p":["第一个边界是立春：流年干支在立春切换。1 月到 2 月初仍在旧年，这一点在断「年初发生的事」时特别重要。","第二个边界是交运：大运在交运日期切换，不是 1 月 1 日。交运常在年中某月某日，前后分属两步运。","取交集的方法：把当年的时段切成三段——立春前（旧年旧运）、立春后到交运前（新年旧运）、交运后（新年新运）。三段各写一句，不要混。","实战价值：当事人说「去年三月出的问题」，你就能定位到具体是哪一段，而不是笼统说「去年流年不利」。"],"s":["查当年立春时刻。","查交运日期。","把年份切成三段。","每段写流年干支与所属大运。"],"e":"某人 2023 年 3 月 16 日交癸丑运：2023 年 1 月 1 日—2 月 4 日（立春前）属壬寅年壬子运；2 月 4 日—3 月 16 日属癸卯年壬子运；3 月 16 日之后属癸卯年癸丑运。同一公历年，三段三张盘。","pr":"找一位正在交运年的亲友，把这一年切成三段，写出每段的年柱与运柱。","q":[{"question":"流年干支在哪一天切换？","options":["1 月 1 日","立春"],"answer":"立春","explanation":"流年以立春为界，年初仍属上一命理年。"},{"question":"交运当年应当如何判断？","options":["整年按新运","按交运日期切成前后两段"],"answer":"按交运日期切成前后两段","explanation":"交运是具体日期，前后分属不同大运，整年一刀切会错判。"}]},{"id":"L75","b":"应期不是猜年份，是写证据链：原局有什么、大运怎么推、流年怎么触发，每一环都要能指出来。","h":"四段式证据链","p":["第一段事实：原局有什么。要带干支与十神，例如「财星两透、比劫三见」，不许写「命中财旺」。","第二段机制：大运如何改变力量对比。是帮身使能任财，还是助财使更失衡？机制写不出，说明你只是在凑年份。","第三段触发：流年与原局、大运的具体关系（冲、合、伏吟、反吟、补上关键一字）。这是「哪一年」的唯一依据。","第四段反证：什么情况下不成立。例如「若该年支中财被合住，则不构成触发」。没有反证的应期，与算命口诀无异。"],"s":["写原局事实，带干支。","写大运的机制。","写流年的触发关系。","写反证与不确定项。"],"e":"以 TC06（庚午 己丑 壬寅 庚戌，身弱财局成）为例：事实——寅午戌三合火，财成局而身弱；机制——行印比运则能任；触发——流年再引火或冲动财局；反证——若该年支中火被合住，则财局不动，判断不成立。","pr":"选一件已知事件，写一份四段式证据链，然后请别人只看你的文字判断「哪一年」，看能不能对上。","q":[{"question":"应期判断中「触发」指什么？","options":["大运的方向","流年与原局、大运的具体关系"],"answer":"流年与原局、大运的具体关系","explanation":"大运是背景，流年通过冲合伏吟等关系构成触发，才落到具体年份。"},{"question":"为什么必须写反证？","options":["显得严谨","防止事后自圆其说，并给出可推翻条件"],"answer":"防止事后自圆其说，并给出可推翻条件","explanation":"没有反证就无法检验，准与不准都能解释，等于没有判断。"}]},{"id":"L24","b":"神煞、纳音、空亡、胎元都属于辅助信息。它们能提示位置，不能单独断事——这条边界守不住，前面所有结构分析都会被冲掉。","h":"辅助信息的三条使用规则","p":["规则一：只标不判。天乙、文昌、驿马、桃花可以标出位置与查法，但不能写「有文昌必读书好」。要把它们当作「提示去看哪一宫」，而不是结论。","规则二：不可单独成立。任何一条断语，如果去掉神煞就说不出来，那这条断语不该写。结构（旺衰、格局、运年）永远是主干。","规则三：标明流派。神煞的查法各书不同，同一颗「天乙贵人」有以日干查、以年干查两说。写的时候要注一句「按日干查」，别人才知道你在用哪一套。","纳音与胎元同此理：纳音多用于合婚与择日，胎元用于辅助看受孕环境，都不参与旺衰与格局判断。越界使用，读者无法复核，你也无法自证。"],"s":["标出辅助信息的位置与查法。","注明用的是哪一套查法。","检查：删掉这条信息，断语是否还成立。","不成立则删掉断语，只留标记。"],"e":"某盘见驿马在年支。可以写「年支为驿马，传统主早年迁移」，但不能写「你二十五岁必出国」。若真要谈迁移，得看年支是否被冲、大运是否引动、以及当事人现实条件——三条都不具备，就只留一个标记。","pr":"找一张带明显神煞的盘，写两句：一句只作标记，一句试图断事；然后删掉断事那句，说明为什么删。","q":[{"question":"神煞在报告中的正确用法是？","options":["直接断吉凶","只标位置与查法，作提示"],"answer":"只标位置与查法，作提示","explanation":"神煞查法流派不一，且不能独立成立，只能提示去看哪一宫。"},{"question":"一条断语若去掉神煞就说不出来，应当？","options":["保留，神煞也是依据","删掉，说明它依赖辅助信息"],"answer":"删掉，说明它依赖辅助信息","explanation":"结构才是主干，依赖神煞才成立的断语无法复核。"}]},{"id":"L25","b":"读古籍要分三层：原文说了什么、原注怎么解、后人评注又怎么改。三层混读，就会把一家之言当成定论。","h":"原文、原注、评注","p":["原文层：先看它到底写了哪几个字。古文极简，一个「用」字可能是「取为用神」，也可能是「使用」，不能凭现代语感补全。","原注层：注者往往带自己的体系。同一句原文，徐子平一系与后来的调候派解释可以完全不同。要看清注者是谁、属于哪一系。","评注层：民国以后的评注常把原文按当时流行的格局法重排，甚至改写原文以合己意。引用时要注明「据某本」而不是「古书说」。","操作要求：写报告引用古籍时，至少给出书名、篇名、以及你依据的版本或注家。给不出，就当作没读到——这一点比多背几句断语重要得多。"],"s":["抄下原文，不改字。","标出注者与所属体系。","查是否有异文或后人改动。","引用时写明书名、篇名与依据版本。"],"e":"《子平真诠》论格局，原文与沈孝瞻自注、徐乐吾评注在「用神」一词的所指上并不完全一致：原文多指「月令所用」，评注有时扩为「全局所需」。若不加区分地引「古人说用神就是月令」，就会把一家之言说成通说。","pr":"取一段古籍原文，抄下原文、找到至少两家注解，写出两家的分歧点，并说明你采用哪一家、为什么。","q":[{"question":"引用古籍时最起码要交代什么？","options":["只要说「古书说」","书名、篇名与依据版本或注家"],"answer":"书名、篇名与依据版本或注家","explanation":"不交代来源就无法核对，也容易把一家之言当成通说。"},{"question":"原注与后人评注的关系是？","options":["完全一致","可能体系不同，甚至改动原文"],"answer":"可能体系不同，甚至改动原文","explanation":"评注常按当时流行体系重排，读时必须分层。"}]},{"id":"L26","b":"证据卡是把「一桩事实」变成「可复核的一条记录」。它不负责解释，只负责让解释有落脚处。","h":"一张卡片的五个字段","p":["字段一：时间。要精确到月，能到日更好。只写年份的证据，无法用来验证应期。","字段二：事实。写发生了什么，不写你的解释。「2023 年 3 月换工作」是事实；「2023 年因官星动而升迁」是解释，要分开。","字段三：来源。当事人自述、家人转述、公开记录，三者的可信度不同，必须标。","字段四：可对应的盘面元素。哪一柱、哪一宫、哪一组关系。字段五：反证。这个事实有没有别的解释？写不出反证，说明你只是在凑。"],"s":["写时间，精确到月。","写事实，不作解释。","标来源与可信度。","写盘面元素与至少一条替代解释。"],"e":"卡片示例——时间：2023 年 3 月；事实：从 A 公司离职、入职 B 公司，职级未变；来源：当事人自述；盘面：流年卯与日支戌合、大运癸丑偏财透；替代解释：行业整体跳槽潮，与经济周期有关，未必由命理因素驱动。","pr":"为一位亲友建三张证据卡，每张都要写出「替代解释」；写不出的，说明这条证据还不该用。","q":[{"question":"证据卡中的「事实」与「解释」应当？","options":["合并写更省事","分开写"],"answer":"分开写","explanation":"混写会把解释当成事实，事后无法检验解释是否成立。"},{"question":"为什么每张卡都要写替代解释？","options":["为了凑字数","防止把任何事都归因于命理"],"answer":"防止把任何事都归因于命理","explanation":"现实事件常有多重成因，不写替代解释就会高估命理因素。"}]},{"id":"L27","b":"只记说中的，永远学不会。这一讲专门处理失败、反例与流派分歧——它们是校正判断的唯一来源。","h":"三类必须留档的材料","p":["失败案例：批错的那几张盘，错在哪一步——排盘、旺衰、取用、应期。四类分开记，才能看出自己的系统性偏差。","反例：结构成立但事件没发生。这类最有价值，因为它直接挑战你的取法。常见原因是：结构成立但运未到、现实条件不允许、或你的取法本身过宽。","流派分歧：同一张盘两种取法结论相反。不要急着选边，先把两套推理各写一遍，看哪一步开始分岔——分岔点往往就是这门学问真正的争议所在。","制度：每十张盘复盘一次，统计四类错误各几次。数字比感觉可靠，也比「最近好像准了」有用。"],"s":["建一张错题表，四列：排盘、旺衰、取用、应期。","每次批错，归入其中一列。","每十张统计一次。","针对最多的那一类，回补对应讲次。"],"e":"常见偏差示例：连续三张盘都判「身弱」——不是盘都弱，而是你的得势一栏习惯性漏数明干印比。这类偏差只有统计才看得出来，单看一张盘永远发现不了。","pr":"回顾你批过的盘（哪怕是练习盘），按四类归档，写出你最多的一类是哪一类。","q":[{"question":"反例（结构成立但事件未发生）的价值在于？","options":["证明命理无用","直接挑战并校正你的取法"],"answer":"直接挑战并校正你的取法","explanation":"反例迫使你检查是运未到、条件不允许，还是取法过宽。"},{"question":"复盘时统计四类错误的作用是？","options":["知道谁对谁错","发现系统性偏差"],"answer":"发现系统性偏差","explanation":"单张盘看不出习惯性错误，统计才能暴露。"}]},{"id":"L28","b":"测评不是考试，是设计一组能让「会」与「不会」分开的任务。设计得好，你自己就能给自己判分。","h":"三级任务：复算、判断、表达","p":["第一级复算：给出生数据，要求排出四柱、藏干、十神。答案唯一，对错分明。这一级只测「会不会算」。","第二级判断：给一张盘，要求写四栏旺衰、取格、给用神方向。答案不唯一，但要看「证据是否齐、条件是否写、反证有没有」。","第三级表达：给一位当事人，要求写一份 800 字报告，并当面讲 10 分钟。这一级测的是「能不能让人听懂并追问」。","评分表要具体：每级列三到五条可勾选的项（如「四栏齐全」「用神带条件」「写了反证」），勾不满就不算过。模糊的「优秀/良好」没有校正作用。"],"s":["设计三组任务，逐级加难。","每组写三到五条可勾选评分项。","自己先做一遍，记录卡在哪。","请他人按评分表给你判一次。"],"e":"二级任务示例：给 TC05，要求①四栏齐全并带干支②指出格名与成格条件③写出用神并附条件④写一条反证。四项各 25 分，75 分以下重做。这样「感觉学会了」就骗不过去。","pr":"按三级任务给自己出一套测评，做完后请一位懂行的人按你的评分表打分。","q":[{"question":"一级「复算」任务主要测什么？","options":["表达能力强弱","会不会算"],"answer":"会不会算","explanation":"复算答案唯一，只检验排盘与查表的准确性。"},{"question":"评分项为什么要写成可勾选的条目？","options":["方便打分","让「会」与「不会」可分辨，避免模糊评价"],"answer":"让「会」与「不会」可分辨，避免模糊评价","explanation":"模糊等级无法校正，具体条目才能指出缺哪一项。"}]},{"id":"L29","b":"解释要带出处。不是摆学问，是让读者能顺着你的路径去核对——这是「可信」与「像那么回事」的分界。","h":"三段式解释：依据、推理、边界","p":["依据段：指出盘面事实与所本之法。「月令戌土为偏财，本页按本气取格」——事实与口径同时交代。","推理段：把事实连成链。「财旺而日主 27 分偏弱，故取印比帮身；印在年干壬水，有根于子」。每一环都能被指认。","边界段：说明这条解释不覆盖什么。「此判断只涉及力量对比，不涉及具体行业与事件」。边界写得越清楚，可信度越高。","如果借助 AI 或检索工具生成解释，必须复核三件事：引用的书是否存在、原文是否被改动、结论是否超出所引原文的范围。三件里有一件不对，就整段弃用。"],"s":["写盘面事实与所用口径。","把推理拆成可指认的环节。","写清不适用的范围。","引用则核书名、原文、范围三项。"],"e":"示例：「月令戌土为偏财，本页以本气取格，故列偏财格（依据）；财 3.0 而日主 27 分，财多身弱，取印比（推理）；此结论只谈力量对比，不推断具体职业与年份（边界）。」三句话，任何一句都能被单独质疑。","pr":"写一段 200 字的解释，要求每句都能被单独质疑；再删掉所有无法被质疑的句子。","q":[{"question":"带出处的解释必须交代什么？","options":["只交代结论","盘面事实、所用口径、推理链与边界"],"answer":"盘面事实、所用口径、推理链与边界","explanation":"四者齐备，读者才能复算并指出你哪一步错了。"},{"question":"使用 AI 生成的解释时，必须复核哪三项？","options":["字数、格式、语气","书是否存在、原文是否改动、结论是否超出范围"],"answer":"书是否存在、原文是否改动、结论是否超出范围","explanation":"生成内容最容易在引书与范围上失真，三项都要核。"}]},{"id":"L45","b":"详批话术不是修辞，是把推理讲到对方能复述。说不清，说明你自己还没想清。","h":"四句话结构：事实、判断、条件、留白","p":["事实句：先说盘上有什么，用对方听得懂的话。「你这一步运是印星当令，等于外部资源比较多」。","判断句：给出方向，不给结果。「所以你更适合在有平台的机构里做，而不是单打独斗」。","条件句：说清成立条件。「如果这两年是换岗而不是创业，这个判断会更明显」。","留白句：主动说不知道。「具体哪一年动，要看你自己有没有在准备，这一层我判断不了」。留白不是示弱，是让对方知道边界在哪。"],"s":["先用一句事实开场。","再给方向，不给结论。","补一句成立条件。","最后说清哪一层你判断不了。"],"e":"反例：「你今年必有大变，注意身体。」——没有事实、没有条件、没有边界，只有情绪。正例：「你这一步是财星当令而身偏弱，做事机会多但容易摊太开；如果今年同时接两个项目，压力会明显；具体健康我不断，只提醒你别把作息压到极限。」","pr":"把一段你写过的判断改成四句话结构，念给一个不懂命理的人听，请他复述——他能复述出条件句，才算讲清。","q":[{"question":"详批话术中「留白句」的作用是？","options":["显得谦虚","说明边界，让判断可被检验"],"answer":"说明边界，让判断可被检验","explanation":"主动说明哪一层判断不了，反而提高整体可信度。"},{"question":"「你今年必有大变」这类表述的问题在于？","options":["不够委婉","无事实、无条件、无边界"],"answer":"无事实、无条件、无边界","explanation":"三样都缺，既无法核对也无法反驳，属于不可证伪的断言。"}]},{"id":"L76","b":"这一讲是纠错训练：把市面上最常见的几种错断摆出来，逐条改成能站得住的表述。","h":"五类高频错断","p":["错断一：见神煞断事。「带桃花必出轨」——错在把标记当结论。改法：标位置，再谈日支与运年是否同时被引动。","错断二：见财断富。「财星多必有钱」——错在忽略身能否任、有无库。改法：写「财有量，能否守住看身与库」。","错断三：见冲断灾。「日时相冲必离婚」——错在把关系当事件。改法：写宫位、写被冲掉的是什么、写有无合解。","错断四：见弱断从。「身弱就当从格」——错在跳过无根验证。改法：先逐支查藏干，写否证条件。错断五：见合断化。「天干相合即化气」——错在漏条件。改法：核月令、化神之根、有无冲破。"],"s":["把错断原话抄下来。","指出它跳过了哪一步验证。","补上被跳过的那一步。","改写成带条件的表述。"],"e":"原话「你比劫多，必被朋友骗钱」→ 跳过：比劫是否透干、财是否有根、有无官杀制劫。改写：「比劫三见而财透，属分夺结构；若行运再见比劫而无官杀制，合作分账容易起争议——具体是否发生，要看实际合作关系。」","pr":"收集五句你听过的断语，逐句按四步改写，写完后检查每句是否都带上了条件。","q":[{"question":"「带桃花必出轨」错在哪一步？","options":["排盘","把辅助标记直接当结论"],"answer":"把辅助标记直接当结论","explanation":"神煞只能提示位置，不能独立成立，须结合日支与运年。"},{"question":"「身弱就当从格」缺了哪一步验证？","options":["查藏干确认是否真的无根","查大运顺逆"],"answer":"查藏干确认是否真的无根","explanation":"从格要求日主无根，一个余气就能否掉，必须先查藏干。"}]},{"id":"L33","b":"男命读婚姻要三样同时看：妻星（财）、妻宫（日支）、以及两者有没有被引动。只看星是耍流氓，只看宫是瞎猜。","h":"星、宫、引动，三项齐全才写","p":["妻星：以财为妻星。正财偏财并见，叫「财混杂」，传统主感情选择多；但只有财星而无宫位引动，仍不足以断事。财透而虚（无根），也主关系浮而不实。","妻宫：日支。日支坐财为「星宫同位」，关系较集中；日支坐比劫，主竞争者多；日支坐官杀，主压力来自关系本身；日支被冲被合，主关系有变动。","第三项是引动：大运或流年冲合日支、财星到位或受克，才构成「什么时候」。三项齐了，才能写「某段时间关系易起变化」。","必须守住的边界：不写「必娶谁」「必离婚」「妻贤不贤」。盘只能描述关系的结构倾向，不能指定具体的人与结果。"],"s":["标出财星位置、旺度、有无根。","看日支坐什么，与日主什么关系。","查日支是否被冲合。","查运年是否引动财星或日支。"],"e":"甲午日、财为土。若支中见戌未而财旺，日支午为食伤之地（木生火、火生土），属「食伤生财而财不入宫」，感情多由自己输出而生，但关系不易定下来。要写清「财有路、宫未合」，不能一句「婚姻不顺」。","pr":"取一张男命盘，分别写妻星、妻宫、引动三项，各带干支；再写一句「这条判断不能被推成什么」。","q":[{"question":"男命读婚姻至少要同时看哪三项？","options":["财星、日支、运年引动","只看财星多少","只看日支"],"answer":"财星、日支、运年引动","explanation":"星、宫、引动三者缺一，结论就无法落到时间与结构上。"},{"question":"日支坐比劫，传统上提示什么？","options":["关系集中","竞争者多、分夺"],"answer":"竞争者多、分夺","explanation":"日支为妻宫，坐比劫即同类占位，主竞争与分夺之势。"}]},{"id":"L34","b":"男命的财不是孤立的：它由食伤生出来，被比劫分走，被官杀护住。三条线一起看，才知道财是「来路通」还是「守不住」。","h":"财的三条线","p":["生线：食伤生财。有食伤则财有来源，无食伤则财靠外缘（薪水、家业）。食伤旺而财弱，是「能挣不留」；财旺而食伤弱，是「有得而无源」。","分线：比劫夺财。比劫成群而财透，主分配争议、合伙分账。有官杀制比劫则争势减，无制则争势显。","护线：官杀卫财。财旺而身弱时，官杀能约束比劫，但也耗身；所以护财与帮身常冲突，要写清取哪一头。","写法：「财有源（食伤），有分（比劫），有护（官杀）」三句写完，再给一句取舍。三句缺一句，财的判断就不完整。"],"s":["找食伤，判财是否有源。","找比劫，判有无分夺。","找官杀，判有无护卫。","写取舍：帮身还是护财。"],"e":"庚午 辛巳 丁酉 乙巳：财为金，酉为财根；食伤为土（局中弱），财源不足；比劫为火，三见而透，分夺明显；官杀为水，局中不见，无护。三句合写：「财有根而无源，分夺重而无护，故分配是主要问题」。","pr":"取一张男命盘，写财的生、分、护三句，再给一句取舍；说明你为什么取这一头。","q":[{"question":"「食伤生财」在男命财的判断中说明什么？","options":["财有来源","财必多"],"answer":"财有来源","explanation":"生线只说明来路是否通，与财的绝对量无关。"},{"question":"官杀卫财与帮身常常冲突，是因为？","options":["官杀克身","官杀既能制比劫护财，又会耗日主"],"answer":"官杀既能制比劫护财，又会耗日主","explanation":"护财与帮身方向相反，必须明写取舍。"}]},{"id":"L36","b":"女命读婚姻，星是官杀、宫是日支。官杀混杂与官杀清纯，读法完全不同；而「清」与「混」要看能不能取清。","h":"官杀先看混与清","p":["官杀混杂：正官七杀同时透出。传统主选择多、压力多头。但混杂有解——去其一（合去或用食伤制其一），叫「取清」，取清之后反而结构更集中。","夫宫：日支。日支坐官杀为星宫同位，关系集中；坐比劫主竞争；坐食伤主自己主导；被冲被合主变动。","第三项仍是引动：运年冲合日支、官杀到位或受制，才落到时间。这一点与男命同法，无性别差异。","边界：不写「必嫁贵夫」「必二婚」。官杀混杂最多说明「关系选择与压力并存」，能不能取清要看制化条件与运，不能直接推成婚姻次数。"],"s":["标出正官、七杀各自位置。","判是否可「取清」，用什么取。","看日支坐什么、有无冲合。","查运年对官杀与日支的引动。"],"e":"乙丑 庚辰 甲戌 辛未（坤造）：庚为七杀透月干、辛为正官透时干，官杀混杂；日支戌为财，非官杀之位；食伤弱（0.8）、印薄（0.9），取清之力不足。故写作「官杀混杂而难以取清，压力多头，关系选择易反复」，止于此，不推婚次。","pr":"取一张女命盘，判断官杀能否取清，写出取清所用的字与条件；写不出条件就只写「混杂」。","q":[{"question":"「官杀取清」指的是？","options":["把官杀全部去掉","去其一，使结构集中"],"answer":"去其一，使结构集中","explanation":"取清不是消灭官杀，而是合去或制住其中一个，使力量集中。"},{"question":"女命夫宫指哪一柱？","options":["年支","日支"],"answer":"日支","explanation":"日支为夫妻宫，男女同法。"}]},{"id":"L37","b":"伤官见官是传统里最吓人的组合之一。真正要判断的是「有没有制化」：有制是才华受约束，无制才是冲突。","h":"伤官与官杀的四种关系","p":["第一种：伤官见官而无制。官星被伤，传统主与权威、规则冲突。这时要写「与制度摩擦的结构」，不写「必犯官非」。","第二种：伤官见官而有印制。印能制伤，伤不伤官，结构转为「有才气而守规矩」，这是伤官配印的另一面。","第三种：伤官见杀。七杀本已烈，伤官再去激，冲突更直接；若有印化杀、有食伤制杀，则转为可控。","第四种：伤官生财而不见官。财为出口，才华转成收益，与传统「伤官要制」的说法不同，需按格局看。判断关键始终是：有没有出口、出口通不通。"],"s":["标出伤官与官杀的位置。","查有无印来制伤。","查有无财可泄。","写「有制」还是「无制」，并给条件。"],"e":"戊辰 庚申 己未 丙寅（坤造）：伤官庚透月干，官星为木（寅中甲），印为丙在时干。丙火制庚，伤不伤官，故写作「伤官见官而有印制，才气受约束，反成结构」，与「伤官见官为祸」的笼统说法不同。","pr":"找一张伤官与官杀并见的盘，判断属于四种关系里的哪一种，写出判断依据。","q":[{"question":"伤官见官，有印制与无制，结论差别在于？","options":["没有差别","有制则才华受约束，无制则与规则冲突"],"answer":"有制则才华受约束，无制则与规则冲突","explanation":"印能制伤，使伤不伤官，结构性质随之改变。"},{"question":"伤官生财而不见官，应如何看？","options":["仍按伤官见官论","按出口是否通畅论"],"answer":"按出口是否通畅论","explanation":"财为出口时，重点在输出能否落地，不必套用「伤官要制」。"}]},{"id":"L38","b":"女命的事业与主体性，看的是「有没有自己的输出口」，而不是「官星好不好」。食伤、财、印三者决定她能不能自己立住。","h":"输出口在哪里","p":["食伤为表达与创造，是主动输出。食伤有根而不过旺，主体性强；食伤过旺无制，输出失控、难以持续。","财为落点与分配。食伤生财，说明输出能转成资源；有食伤无财，说明有想法难变现；有财无食伤，说明靠既有资源而非创造。","印为背书与庇护。印适度则有所依，印过重则依赖，压住食伤就变成「有想法不敢做」。判断要看印与食伤的相对强弱。","官杀是外部要求，不是主体性本身。把「官星旺」直接读成「事业好」，是把外部压力当成内在能力，这是女命论里最常见的错位。"],"s":["看食伤有无根、是否过旺。","看食伤与财是否成线。","看印与食伤的相对强弱。","写「输出口在哪、通不通」。"],"e":"癸酉 癸亥 戊申 丁巳（坤造）：食伤为金（酉、申），有根；财为水（两癸、亥），食伤生财成线；印为丁巳，一点。结构写作「输出口清楚：创造转资源的路通，限制在日主 26 分偏弱，需帮身才承得住」，而不是「官星如何」。","pr":"取一张女命盘，写出输出口在哪、通不通、限制是什么，全程不提官星。","q":[{"question":"判断女命事业与主体性，主要看什么？","options":["官星旺不旺","食伤、财、印构成的输出口"],"answer":"食伤、财、印构成的输出口","explanation":"官杀是外部要求，主体性来自输出能力与资源转化。"},{"question":"印过重会怎样影响主体性？","options":["增强执行力","压住食伤，变成有想法不敢做"],"answer":"压住食伤，变成有想法不敢做","explanation":"印重则依赖与顾虑增加，食伤被压，输出受阻。"}]},{"id":"L40","b":"同一张盘换性别，结构完全不变，取象与落点全变。这一讲用一张盘并读写两遍，把「共通」与「差异」钉死。","h":"前两句必须一模一样","p":["并读的规矩：旺衰与格局两句必须逐字相同。若两段写出来结构判断不同，说明你在按性别调整事实，那是错的。","差异只出现在取象：男命财为妻、官杀为子女；女命官杀为夫、食伤为子女。同一组十神，在两段里代表不同的人。","第二层差异在落宫：男命看财与日支，女命看官杀与日支。星不同，宫相同——这是并读时最容易混的地方。","价值：并读能检验你有没有偷懒。很多人写男命就套「财旺妻贤」，写女命就套「官旺夫贵」，并读一遍立刻露馅。"],"s":["先写共通两句：旺衰、格局。","男命段：写财星与日支。","女命段：写官杀与日支。","对照两段，确认结构句未变。"],"e":"乙丑 庚辰 甲戌 辛未：共通句「甲木失令偏弱、官杀混杂而印薄，取印化杀为急」。男命段补「财为土，支中丑未戌三土，财旺而身弱，妻宫戌被冲，主关系变动」；女命段补「官杀混杂难取清，夫宫戌被冲，主关系选择反复」。结构句一字未改。","pr":"取一张盘，写共通两句加男、女两段取象，然后检查结构句是否真的完全相同。","q":[{"question":"同盘男女并读时，哪部分必须完全相同？","options":["取象部分","旺衰与格局"],"answer":"旺衰与格局","explanation":"结构判断与性别无关，若不同说明在按性别改事实。"},{"question":"男命与女命的「宫」是否相同？","options":["不同","相同，日支都是夫妻宫"],"answer":"相同，日支都是夫妻宫","explanation":"星不同（男财女官），宫相同（日支）。"}]},{"id":"L41","b":"六亲取法有分歧，但宫位是共同的：年月看父母与根基，月柱兼兄弟，时柱看子女。宫先定，星再补。","h":"宫为主，星为辅","p":["父母：年柱主祖上与早年环境，月柱主父母。星上以偏财为父、正印为母（多数流派男女同此）。宫与星同指，才谈得上明确。","兄弟：月柱兼看，星上以比劫为兄弟姐妹。比劫成群主同辈多、分夺多；比劫被官杀制则同辈助力转为约束。","子女：时柱为子女宫，星上男命以官杀为子女、女命以食伤为子女。时柱被冲被合，主子女宫有变动；但「几个子女」不在可判断范围内。","分歧要标：父母星的取法各家不同（有以偏财为父、有以年柱为父），子女星的取法也有异说。写报告时注明所用一套，不要含混过去。"],"s":["先定宫：年、月、日、时各主谁。","再取星：父母、兄弟、子女各以何为星。","看星与宫是否同指。","注明所用取法，标出异说。"],"e":"庚辰 庚辰 己未 甲子：年月两柱皆庚辰，伤官重叠——父母宫与兄弟宫同时见伤官，传统主同辈多、家庭资源分散；时柱甲子，甲为正官，男命以官杀为子女，故子女宫见子女星，且子水为财。宫星同指者，才写。","pr":"取一张盘，按宫、星两步写父母、兄弟、子女三段，每段注明所用的取法。","q":[{"question":"六亲判断应当先定什么？","options":["先定星","先定宫位"],"answer":"先定宫位","explanation":"宫位是共同框架，星各家有异说；先宫后星才不乱。"},{"question":"「几个子女」能否由盘判断？","options":["能，看时柱","不能，超出可判断范围"],"answer":"不能，超出可判断范围","explanation":"盘只能描述子女宫的结构与变动，不能指数量。"}]},{"id":"L61","b":"婚姻质量不是一个「好/不好」的开关，是四个维度：星是否清、宫是否稳、结构是否被破坏、现实条件是否允许。","h":"四维打分，不给结论","p":["星：男看财是否混杂、有无根；女看官杀是否混杂、能否取清。星混不等于关系乱，只说明选择与压力多头。","宫：日支是否被冲、被合、被刑。宫被冲主变动，宫被合主牵连；宫稳而坐喜神，关系相对稳定。","结构：婚姻相关的结构有没有被破坏——比劫夺财（男）、伤官见官无制（女）、印重压食伤（女命输出受阻）。破坏条件要写具体。","现实：这是最容易被忽略的一维。盘只能给倾向，结婚早晚、对象类型、关系质量，受教育、地域、家庭安排影响极大。四维里缺了这一维，判断就会过度决定论。"],"s":["写星：位置、旺度、清混。","写宫：日支坐什么、有无冲合。","写结构：有无破坏及其条件。","写现实：哪些因素盘管不到。"],"e":"丙戌日、女命、官杀为水。若局中官杀两见而无制，日支戌为食伤之地（火生土），星混而宫不静；此时写作「关系选择多头、自身主导性强，易反复」，并补一句「具体婚恋受现实安排影响，不由此断定」。","pr":"取一张盘，按四维各写一句，最后写一句「这一维我判不了什么」。","q":[{"question":"婚姻判断中「宫」指什么？","options":["日支","月柱"],"answer":"日支","explanation":"日支为夫妻宫，星随性别不同，宫则同法。"},{"question":"为什么必须写「现实」这一维？","options":["显得全面","盘只给倾向，关系质量受教育、地域、家庭安排影响"],"answer":"盘只给倾向，关系质量受教育、地域、家庭安排影响","explanation":"缺这一维就会把结构倾向说成必然结果，属过度决定论。"}]},{"id":"L62","b":"婚恋应期要两个条件同时满足：星到位，宫被引动。只有星动而宫不动，多为机会；只有宫动而星不到，多为变动而非成婚。","h":"星到、宫动、窗口","p":["星到：男命财星在流年出现或得地；女命官杀在流年出现或得地。星到是「有对象/有机会」的必要条件。","宫动：日支被流年冲、合、刑。宫动是「关系状态改变」的必要条件。星到而宫不动，常表现为「遇到但没成」。","窗口：星与宫同时被引动的年份，才是高概率窗口。若两步大运也同时引动，窗口更强；若大运逆着走，窗口会推迟。","写法：「2027 丁未年，财星得地（星到），未与日支卯合（宫动），故为窗口；但大运在印地，帮身不足，成事需现实配合。」——星、宫、运三层都在句子里。"],"s":["标流年是否带来星。","标流年是否冲合日支。","看大运是顺是逆。","三者同向才写「窗口」，否则写「有机会」。"],"e":"男命日支卯，2027 丁未：未与卯半合（宫动），流年丁为伤官、未中己为财（星到），两者同年。若大运在帮身之地，则写「关系易定」；若大运耗身，则写「有机会而难定」。差别只在运，不在年。","pr":"为一张盘找出未来十年里「星宫同动」的年份，列出来并标出哪一年大运也配合。","q":[{"question":"婚恋应期需要哪两个条件同时满足？","options":["星到与宫动","官星旺与财星旺"],"answer":"星到与宫动","explanation":"星到是机会，宫动是关系状态改变，两者同年才构成窗口。"},{"question":"只有宫动而星不到，通常表现为什么？","options":["成婚","变动而非成婚"],"answer":"变动而非成婚","explanation":"宫动主关系状态变化，缺星则多为搬迁、分离、关系调整等变动。"}]},{"id":"L63","b":"事业结构看四样的配合：财（资源）、官（位置）、印（资格）、食伤（能力）。四样齐不齐、通不通，决定一个人靠什么吃饭。","h":"四种吃饭方式","p":["官印相生：靠资格与位置。有官有印，适合体制、大机构、专业执照类路径。印弱则资格不足，官旺无印则压力大而位置虚。","食伤生财：靠能力与交易。有食伤有财，适合技术、创作、经营。食伤弱则能力未成，财旺无食伤则靠资源而非本事。","财官相生：靠资源换位置。财生官，适合经营转管理、资源型岗位。身弱则两头都扛不住。","比劫成群：靠人多与协作，也主分夺。适合团队型工作，但分配机制必须清楚，否则内耗。判断时先问「哪一个链条是通的」，不要四样都说一遍。"],"s":["列财、官、印、食伤各自的旺度。","找哪一条链是通的（官印/食伤财/财官）。","看日主能否承担这条链。","写「靠什么吃饭」一句。"],"e":"己未 己巳 辛丑 戊子：印 5.8 极重、官星不显、食伤 1.6、财 1.5。链条上「印重而无官无财」，写作「靠资格与背书立身，缺少交易与位置的转化；宜在机构内积累，不宜单干」。四样里只写通的那一条，其余注明「弱」。","pr":"取一张盘，写出四样旺度与最通的一条链，再写一句「这个人靠什么吃饭」。","q":[{"question":"「官印相生」主要对应哪类路径？","options":["技术创作","资格与位置（体制、专业执照）"],"answer":"资格与位置（体制、专业执照）","explanation":"官为位置、印为资格，相生则靠资格取得位置。"},{"question":"四样都弱时应当怎么写？","options":["四样各写一遍","说明缺少可用的链条，并指出最缺哪一样"],"answer":"说明缺少可用的链条，并指出最缺哪一样","explanation":"平均用力等于没判断，应指出结构性缺口。"}]},{"id":"L64","b":"从象义到职业，中间隔着一道验证。象义只能给方向（精确/表达/组织/服务），职业必须用当事人的实际任务去核对。","h":"三步：象义—任务—验证","p":["第一步象义：五行与十神给方向。木主生发条达，火主表达显现，土主承载稳定，金主收敛精确，水主流通智巧。这是方向，不是职业名。","第二步任务：把方向转成「日常做什么」。精确（金）对应核对、审计、编码、手术；表达（火）对应讲授、销售、内容；组织（土）对应运营、行政、项目管理。","第三步验证：问当事人「你现在每天做什么、哪部分最累、哪部分最顺」。若象义说「宜精确」而对方实际最怕细节，就要放弃这条推断——现实反馈优先于象义。","纪律：永远不给「你适合做金融/律师/医生」这种断言。给的是「你的结构偏向哪类任务」，职业选择还要看学历、机会、家庭与行业周期。"],"s":["写五行与十神给出的方向。","把方向翻译成具体任务类型。","用当事人的实际经历验证。","验证不符则放弃该推断。"],"e":"己卯 壬申 庚申 丙子：金水成象、比肩 2.6、食神 2.5，象义偏「精确 + 流通」。可写「适合需要核对与流程的工作，如质量、数据、法务支持」；若当事人实际做的是销售且做得很好，则以现实为准，改判为「精确是偏好而非限制」。","pr":"为一位熟人写三条职业方向推断，逐条标注「用什么现实信息可以推翻它」。","q":[{"question":"象义能直接给出职业名称吗？","options":["能","不能，只给方向"],"answer":"不能，只给方向","explanation":"象义给的是任务偏好方向，职业名还受学历、机会、行业影响。"},{"question":"当象义与当事人实际经历冲突时，应当？","options":["坚持象义","以现实反馈为准，修正推断"],"answer":"以现实反馈为准，修正推断","explanation":"现实反馈优先，象义只是假设。"}]},{"id":"L65","b":"事业应期比婚恋更依赖「外部条件」：岗位有没有空缺、行业在不在周期里。盘只能给压力与机会的时点，不能给职位。","h":"三种时点，三种含义","p":["机会时点：官星到位或印星得力，主「有位置/有资格」。但位置是否真的空出来，要看现实。所以只能写「较易被考虑」。","压力时点：官杀过旺而无制，或食伤冲官，主「与规则、上级摩擦」。写摩擦，不写「必被开除」。","转换时点：日支或月柱被冲合，主环境变动（搬迁、换部门、换行业）。冲合落在哪一宫，决定动的是「住所」还是「岗位」。","写法要求：「2028 年官星得地而印来护，属机会时点；若单位当年有岗位调整，被考虑的概率高于平常」——条件句，可核对，不承诺。"],"s":["标出官、印、食伤的流年到位情况。","标出月柱、日支被冲合的年份。","区分机会、压力、转换三类。","每类都写成条件句。"],"e":"男命、月柱为事业起点。若 2029 年流年冲月柱，同时官星透出，则写「岗位或所属部门易有调整，属转换时点；官星同至，调整中较易获得正式位置，但需单位当年确有编制变动」。","pr":"取一张盘，标出未来十年里机会、压力、转换三类时点各一个，全部写成条件句。","q":[{"question":"事业应期为什么必须写成条件句？","options":["显得专业","岗位与行业周期不由盘决定"],"answer":"岗位与行业周期不由盘决定","explanation":"盘只能给压力与机会的时点，是否兑现取决于现实条件。"},{"question":"流年冲月柱，通常提示什么？","options":["健康问题","岗位或所属环境调整"],"answer":"岗位或所属环境调整","explanation":"月柱主事业起点与环境，被冲主变动。"}]},{"id":"L66","b":"财运要问四件事：钱从哪来（来源）、拿不拿得动（承载）、分不分得清（分配）、留不留得住（留存）。四问顺序不能乱。","h":"来源、承载、分配、留存","p":["来源：食伤生财为「自己挣」，财官相生为「资源换」，印重无财为「靠积累与背书」。来源决定收入形态，不决定多少。","承载：日主能不能任财。身弱财旺，机会多而承接不足，典型表现是「忙、摊子大、到手少」。这一层依赖旺衰判断。","分配：比劫夺财、合伙分账。有官杀制劫则分配较清，无制则争议多。这一层最容易被忽略，却是很多人真正的痛点。","留存：财有无库（辰戌丑未）、有无被冲。库被冲开主大进大出；无库主难积。留存的判断要落到具体支，不能空谈「守财」。"],"s":["写来源：靠什么挣钱。","写承载：身能否任财。","写分配：有无分夺、有无制。","写留存：有无库、有无被冲。"],"e":"癸酉 癸亥 戊申 丁巳：来源——食伤（申酉）生财（癸亥），自己挣；承载——26 分偏弱，承接有限；分配——比劫 0.7，分夺轻；留存——无库，财易流动。四问合写：「能挣、难守、分夺少、宜把现金流做成固定安排」。","pr":"为一位亲友按四问写一遍，每一问都要指出对应的干支；写不出的那一问，标注「资料不足」。","q":[{"question":"「承载」这一问依赖什么判断？","options":["旺衰","神煞"],"answer":"旺衰","explanation":"能否任财取决于日主强弱，是财判断的第二层。"},{"question":"财无库通常提示什么？","options":["财多","难以积存"],"answer":"难以积存","explanation":"库主收藏，无库则财易流动，难以积累。"}]},{"id":"L67","b":"财富层级最容易被夸大。古代「富贵」的标准与今天不同，资产定义也完全不同，所以这一讲只做辨读，不做估值。","h":"三个不能直接搬的旧标准","p":["旧标准一：「财旺即富」。古代以田产、俸禄计富，财旺在农业社会确实对应资源；现代财富更多来自组织、技术、金融杠杆，财星旺不等于资产多。","旧标准二：「身弱不任财即贫」。身弱只说明承接力弱，可能表现为「替人管大钱、自己份额小」，这在现代很常见，并不等于贫穷。","旧标准三：「财库丰隆必大富」。库只主收藏倾向，有无库与资产规模无必然关系。","可以写的是相对层级：财有源、身能任、有库、无重分夺者，留存能力较强；反之较弱。这是「结构上的强弱」，不是「多少钱」。写报告时明确这一点，才算守住边界。"],"s":["写财的来源与量。","写身能否任。","写有无库与分夺。","只给相对强弱，不给金额与层级标签。"],"e":"甲木身弱、财 4.2 而有食伤生：结构上「财有源、身不足」，可写「收入机会多而留存弱，宜借平台而非独担」；不能写「身家千万」或「一生清贫」——两者都超出盘能支持的范围。","pr":"找一段你见过的「财富层级」断语，逐句标出它用了哪个旧标准，再改写成结构表述。","q":[{"question":"「财旺即富」在现代为何不成立？","options":["因为财星不重要","因为现代财富来源与古代不同"],"answer":"因为现代财富来源与古代不同","explanation":"古代以田产俸禄计，现代更多来自组织、技术与金融杠杆。"},{"question":"身弱不任财，可能表现为什么？","options":["一定贫穷","替人管大钱而自己份额小"],"answer":"替人管大钱而自己份额小","explanation":"承接力弱指自身份额与掌控，不等于没有资源经过。"}]},{"id":"L77","b":"同一年往往能给出好几种解释。六亲应期的难点不在找关系，而在「哪一宫先动、哪一种解释更贴现实」。","h":"一因多果，一果多因","p":["一因多果：一次丑未冲，可能落在田宅（搬迁、房产），也可能落在长辈（父母健康），还可能落在自身（工作变动）。冲只说明「动」，动在哪要看宫位。","一果多因：一次搬迁，可能是流年冲印（住所），也可能是大运换宫，还可能是现实原因（工作调动）。写报告时要列出至少两种可能，并说明你倾向哪一种、为什么。","资料表的作用：把当事人已知的六亲信息（父母年龄、兄弟姐妹、子女情况）先记下来，再看盘。反过来做，就会把盘套到已知事实上——那是验证不了任何东西的。","纪律：六亲应期只写「哪一宫易动、动的形态是什么」，不写「谁必病、谁必亡」。这是所有议题里伤害风险最高的一类，必须守死。"],"s":["先记六亲资料，不看盘。","标出太岁引动的是哪一宫。","列两种以上解释。","写倾向与理由，不写断言。"],"e":"丁丑 辛亥 丁丑 丁未，某年丑未再冲：可解释为①田宅动（搬迁、置换）②长辈宫动（父母健康或居住变化）③自身工作环境动。三种都成立，须结合当事人年龄与已知资料择一，不能三句全写当结论。","pr":"取一张盘，为同一个流年写三种解释，再说明你会怎么向当事人确认是哪一种。","q":[{"question":"同一次冲落在不同宫，说明什么？","options":["冲没有意义","冲只说明「动」，动在哪看宫位"],"answer":"冲只说明「动」，动在哪看宫位","explanation":"宫位决定所谈的层次，同一关系可落在不同人事上。"},{"question":"六亲资料应当什么时候记录？","options":["看完盘之后按盘套","看盘之前先记事实"],"answer":"看盘之前先记事实","explanation":"先记事实才能避免把盘往已知结论上套。"}]},{"id":"L68","b":"健康篇最容易伤人。传统五行脏腑是一套象义对应，不是医学诊断；本讲只讲怎么读这套象义，以及为什么不能拿它替代就医。","h":"五行对应是象义，不是病理","p":["传统对应：木主肝胆、火主心与小肠、土主脾胃、金主肺与大肠、水主肾与膀胱。这是一套类比系统，用于描述「偏旺偏弱」的方向，不描述具体疾病。","读法只有一种：看哪一行过旺或过弱，写成「注意方向」，例如「木旺土弱，传统主思虑多而脾胃易受牵」。绝不能写成「会得胃病」。","过旺与过弱都可能被提：过旺主「亢」，过弱主「虚」。但两者都只是倾向，与体质、作息、遗传、环境相比，盘的解释力很有限。","必须写进报告的免责句：本段属传统象义推演，不构成医学建议；身体不适应就医。这一句不是套话，是这条内容能不能写的前提。"],"s":["标出五行偏旺偏弱。","对应到脏腑方向。","写成「注意方向」，不写病名。","附上免责说明。"],"e":"丙火三见、土薄水少之盘：传统写作「火偏旺而水不足，注意作息与情绪相关的耗损，宜规律睡眠与补水」。这样写只是方向；若写成「心脏有问题」，就越过了全部边界。","pr":"取一张五行偏枯的盘，写一段 100 字的健康提示，检查里面有没有出现任何病名。","q":[{"question":"五行脏腑对应属于？","options":["医学诊断","传统象义系统"],"answer":"传统象义系统","explanation":"它是类比推演，用于描述偏旺偏弱的方向，不是病理诊断。"},{"question":"健康段落中必须包含什么？","options":["具体病名","免责说明与就医建议"],"answer":"免责说明与就医建议","explanation":"缺这一句，整段内容就越界，且可能造成实际伤害。"}]},{"id":"L69","b":"健康与运年结合时，风险最高。这一讲列清三条不能越的线，以及越线之后会发生什么。","h":"三条线：不诊断、不预测生死、不劝停药","p":["第一条：不诊断。「你肝有问题」是诊断，属医疗行为。可以说「传统象义上木受克，注意休息」，不能说器官有病。","第二条：不预测生死与重病时点。「某年有血光之灾」这类说法既不可证伪，又可能造成严重心理伤害。这是绝对红线，任何流派口径都不能突破。","第三条：不劝停药、不劝改治疗方案。哪怕当事人主动问「我能不能停药」，答案只能是「请问医生」。","可以做的：把运年引动写成「压力期」，提示作息、体检、情绪管理。这类提示有实际价值，且不越界。写法：「这两年官杀旺，属压力期，建议把体检和作息安排上」——是建议，不是判决。"],"s":["检查是否出现病名或诊断句。","检查是否给出年份+重病/生死的组合。","检查是否涉及用药与治疗。","把三条都改成「压力期 + 建议」。"],"e":"错误写法：「2027 年羊刃冲岁，恐有手术。」正确写法：「2027 年冲克较重，属压力期，若本就有慢性问题，建议提前复查、避免熬夜。」同样的盘面信息，一个越界，一个可用。","pr":"把你写过的健康段逐句过一遍三条线，凡越线的句子划掉并改写。","q":[{"question":"「某年恐有手术」这类表述的问题在于？","options":["不够具体","预测重病时点，不可证伪且可能造成伤害"],"answer":"预测重病时点，不可证伪且可能造成伤害","explanation":"属绝对红线，任何流派口径都不能突破。"},{"question":"当事人问「能不能停药」，应当？","options":["按盘判断","请其咨询医生"],"answer":"请其咨询医生","explanation":"用药与治疗超出命理判断范围，只能转介。"}]},{"id":"L70","b":"子女专题的取法分歧最大：男命以官杀为子女、女命以食伤为子女，也有以时柱统看而不分星的。这一讲讲清三套口径与共同边界。","h":"星、宫、以及不能说的话","p":["宫：时柱为子女宫，这是各派共识。时支被冲被合，主子女宫有变动；时柱坐喜神，主与子女关系较顺。宫的部分争议最小。","星：男命以官杀为子女（正官七杀），女命以食伤为子女（食神伤官）。另有流派不分男女，一律以时柱为主、星为辅。写报告时要注明用的是哪一套。","分歧点：子女数量、性别、成就。这三样在不同流派里都有说法，但彼此矛盾且无法验证。本页一律不写。","可以写的：子女宫是否安稳、与子女的关系倾向（亲近/疏远/操心）、子女宫被引动的年份（主变动而非事件）。这些都在结构层面，可被讨论。"],"s":["看时柱是否被冲合。","按性别取子女星并注明口径。","写关系倾向，不写数量与性别。","标出子女宫被引动的年份。"],"e":"己未 己巳 辛丑 戊子（男命）：时柱戊子，戊为正印、子为食神之地；男命子女星为官杀，局中官杀不显，子女宫却安稳无冲。写法：「子女宫安稳，然子女星不显，关系上偏淡或聚少离多——此为结构倾向，不作事实断言。」","pr":"取一张盘，写出子女宫状态、所用取法、以及你决定不写的三项内容及原因。","q":[{"question":"子女宫的共识度最高的部分是？","options":["星","时柱"],"answer":"时柱","explanation":"时柱为子女宫各派通用，星的取法分歧较大。"},{"question":"子女数量与性别能否判断？","options":["能，看时柱","不能，各派说法矛盾且无法验证"],"answer":"不能，各派说法矛盾且无法验证","explanation":"这类内容不可验证，容易造成误导，本页不写。"}]},{"id":"L71","b":"父母看年月两柱，星上以偏财为父、正印为母。宫与星同指，才谈得上明确；不同指，就只能写倾向。","h":"年月分主，星宫合看","p":["宫：年柱主祖上与幼年环境，月柱主父母与成长环境。年柱被冲，主早年环境变动；月柱被冲，主父母宫动或成长环境改变。","星：偏财为父、正印为母，这是多数流派的取法。星透而有根，主父母缘分较显；星弱而被克，主缘分较薄或聚少离多。","同指与不同指：若偏财恰在月柱，星宫同指，父母信息较明确；若偏财在时柱而月柱无财，则星宫不同指，只能写「父亲的影响偏晚或较远」。","边界：不写父母寿元、不写父母疾病、不写「克父母」。传统有「幼年克父母」之说，这类说法既不可证伪又伤人，本页不采用。"],"s":["看年柱、月柱是否被冲合。","取偏财、正印，看位置与根。","判断星宫是否同指。","只写关系倾向，不写寿元疾病。"],"e":"庚辰 庚辰 己未 甲子：年月两柱皆庚辰，比肩重叠，偏财（水）不透而藏于子；父母宫见伤官而非财星，星宫不同指。写法：「父母宫被同辈之气占据，早年资源分散，与父母的关系偏合作型而非庇护型。」","pr":"取一张盘，写出父母宫状态、父母星位置、是否同指，再写一句你拒绝给出的内容及理由。","q":[{"question":"父母星的主流取法是？","options":["偏财为父、正印为母","正官为父、偏印为母"],"answer":"偏财为父、正印为母","explanation":"多数流派以偏财为父、正印为母，但须注明口径。"},{"question":"「幼年克父母」这类说法为何不采用？","options":["因为太古老","不可证伪且可能造成伤害"],"answer":"不可证伪且可能造成伤害","explanation":"这类断语无法检验，且会引发不必要的恐惧与自责。"}]},{"id":"L72","b":"兄弟姐妹与合作分配，都落在比劫上。比劫成群既主同辈多，也主分夺多——同一种结构，两种读法要同时说。","h":"比劫的两面","p":["月柱兼看兄弟宫，星上以比肩劫财为兄弟姐妹。比劫有根而适度，主同辈助力；比劫成群而无制，主资源被分、合作易起争议。","合作分配要看三样：财是否透（有无可分之物）、比劫是否成群（分的人多不多）、官杀是否制劫（有没有规则约束）。三样齐了，分配问题才成立。","比劫也主「同辈支持」。创业团队、同行互助、朋友网络，都在比劫的范围里。只写「夺财」不写「助力」，是把结构读成了一半。","写法：「比劫三见而财透，同辈既是助力也是分力；有官杀制则分配有规则，无制则靠人情，易生摩擦。」一句里两面都写到。"],"s":["看比劫数量与是否透干。","看财是否透、是否有根。","看官杀是否制劫。","同时写助力与分力两面。"],"e":"庚午 辛巳 丁酉 乙巳：比劫（火）三见而透，财（金）透而有根，官杀（水）不见。写法：「同辈网络强，合作机会多；财透而无制，分配靠人情，摩擦概率高，宜先立规则。」","pr":"取一张比劫明显的盘，写助力与分力各一句，再写一条「如何用规则减少摩擦」的建议。","q":[{"question":"比劫成群的结构，应当如何表述？","options":["只写夺财","助力与分力两面都写"],"answer":"助力与分力两面都写","explanation":"比劫既主同辈支持也主分夺，只写一面会失真。"},{"question":"合作分配问题成立需要哪三样？","options":["财透、比劫成群、官杀制劫与否","印旺、官旺、食伤旺"],"answer":"财透、比劫成群、官杀制劫与否","explanation":"有可分之物、有分的人、有无规则，三者共同决定分配格局。"}]},{"id":"L35","b":"这一讲不引入新知识，只把前面的方法串成一次完整走盘。男命示范选一张财旺身弱的盘，因为它的取舍最容易讲清。","h":"从核盘到收束，六段走完","p":["第一段核盘：出生数据、时区、真太阳时、换日口径，四项写清。示范盘为壬戌 庚戌 甲午 甲子，乾造，甲木生戌月，失令。","第二段四栏：得令 12/40（戌月本气戊土，偏财耗身）；得地 0/35（四支无甲）；得势 15/25（壬偏印、甲比肩）；克泄耗中财 3.0、食伤 1.9、官杀 2.4。合计 27 分，偏弱。","第三段取用：扶抑取印比；调候为秋末渐凉、水已有根，不必另取；格局本气偏财透庚，列偏财格，破在比劫。三条合写：「取印比帮身，印优于比，因官杀亦重」。","第四段大运：辛亥官印（官星当令，帮力有限）、壬子印地续帮、癸丑半帮、甲寅大帮、乙卯帮、丙辰转耗、丁巳耗、戊午大耗。走势先扬后抑，四十岁后宜守。","第五段分宫：日支午为夫妻宫，与年支戌半合火（食伤），主感情由自身输出而起；月柱庚戌为事业起点，财星坐印，靠资源与资格起步；时柱甲子，比肩坐印，晚景有同辈支撑。","第六段收束：三条结论各带条件与反证，并写明「不判断的具体事项」——不写婚次、不写金额、不写职位。整份示范控制在 800 字内，每句都能被单独质疑。"],"s":["核盘四项写清。","四栏各带干支与分数。","取用三条并列，标优先。","八步大运连成走势线。","分宫写星与宫。","收束写条件与反证。"],"e":"收束示范：「此盘财旺身弱，得印比则能任，故 1993—2013 两步印运为主要上行段（条件：印不被财坏）。2013 后转食伤财地，宜守成不宜扩张（反证：若当事人已于上行段完成资本积累，则后段可转投资而非收缩）。婚恋不作次数判断，仅提示日支与财星同被引动之年易有变化。」","pr":"照六段结构，写一份 800 字男命示范报告，写完自查：每段是否都有干支依据。","q":[{"question":"示范报告中「四栏」的作用是？","options":["凑字数","让旺衰结论可被逐项核对"],"answer":"让旺衰结论可被逐项核对","explanation":"四栏各带干支与分数，读者可逐项质疑，结论才站得住。"},{"question":"收束段必须包含什么？","options":["结论数量","条件、反证与不判断的事项"],"answer":"条件、反证与不判断的事项","explanation":"三者齐备，报告才是可检验的判断而非断言。"}]},{"id":"L39","b":"女命示范选官杀混杂的盘，因为它的边界最需要示范：到哪里必须停，停了之后怎么写。","h":"示范「写到哪里为止」","p":["核盘：乙丑 庚辰 甲戌 辛未，坤造，甲木生辰月，财旺。","四栏：得令——辰月本气戊土为偏财，失令，12 分；得地——四支无甲，同类只落在藏干：辰藏乙（中气）+6、未藏乙（余气）+2，合计 8 分；得势——年干乙劫财 +7，月干庚、时干辛为官杀不计帮扶，合计 7 分；克泄耗——财 4.6、官杀 3.1。三项相加 27 分，偏弱。","取用：官杀混杂而印薄，先取印化杀，次取比劫帮身；调候为春末土厚，需木疏土；格局列「财旺生官杀」，写作「格成于财，破于身弱不能承」。","分宫：日支戌为夫妻宫，被辰冲（辰戌冲），主关系宫动；月柱庚辰为事业起点，七杀坐财，压力型环境；年柱乙丑，劫财坐财，早年资源分散。","边界示范：日支被冲 + 官杀混杂 + 印薄，传统会直接写「婚姻多波折、易二婚」。本报告只写到「关系宫易动、选择多头、需现实条件配合」，并明确写出「不判断婚次与对象类型」。","收束：三条结论——压力型环境宜借平台、关系宫易动宜慢定、财旺身弱宜先立承接力。每条附反证一句。"],"s":["核盘与四栏按男命同法写。","取用写「先化后帮」的次序。","分宫标出被冲之宫。","在越界处明确写「不判断什么」。","收束三条，各附反证。"],"e":"越界与守界的对照——越界写法：「辰戌冲动夫妻宫，官杀混杂，主二婚。」守界写法：「辰戌冲动夫妻宫，主关系状态易变；官杀混杂而印薄，主选择与压力并存。此为结构倾向，婚次不在可判断范围。」同一盘面，后者可被讨论，前者只能被相信或不信。","pr":"取一张女命盘，写完整报告，并在结尾单列一节「本报告不判断的事项」，至少三条。","q":[{"question":"女命示范中最关键的示范点是什么？","options":["断语写得多准","写到哪里必须停"],"answer":"写到哪里必须停","explanation":"官杀混杂最容易被过度解读，守界比断语更能体现水平。"},{"question":"「本报告不判断的事项」一节的作用是？","options":["免责","明确边界，使报告可被检验"],"answer":"明确边界，使报告可被检验","explanation":"写清不判断什么，读者才知道结论的适用范围。"}]},{"id":"L46","b":"十二步是整盘报告的标准流程。这一讲把十二步排成一张可勾选的清单，做完一步勾一步，防止跳步。","h":"十二步清单","p":["第 1—4 步定盘：①收资料 ②核时区与夏令时 ③真太阳时与换日口径 ④排四柱并复核藏干十神。四步任一存疑，后面全部作废重来。","第 5—8 步结构：⑤四栏旺衰 ⑥取格与护破 ⑦取用三法并列 ⑧大运顺逆与交运日期。这四步是报告主干。","第 9—11 步人事：⑨分宫（年月日时各主什么）⑩选定议题（婚姻/事业/财/六亲）⑪运年引动落到具体年份。","第 12 步收束：写结论、条件、反证、不判断事项。十二步走完约需 90 分钟；熟练后 40 分钟。少于 30 分钟完成的报告，多半跳了步。"],"s":["打印或手写十二步清单。","每完成一步打勾并写一句依据。","任一步写不出依据，回到上一步。","最后统计用时，与 90 分钟对照。"],"e":"常见跳步：直接从第 4 步跳到第 11 步（有盘就断年），中间的旺衰与取用全靠印象。这类报告的典型特征是「结论很多、依据很少」，一被追问就答不上。","pr":"用十二步清单完整走一张陌生盘，记录每步用时，找出你花时间最多与最少的两步。","q":[{"question":"十二步中哪几步属于「结构」主干？","options":["第 1—4 步","第 5—8 步"],"answer":"第 5—8 步","explanation":"旺衰、取格、取用、大运是报告的结构主干。"},{"question":"报告的典型跳步表现是？","options":["结论多而依据少","依据多而结论少"],"answer":"结论多而依据少","explanation":"跳过旺衰与取用直接断年，就会出现大量无依据的结论。"}]},{"id":"L47","b":"闭卷作业的目的不是考倒你，是让你在没有参考答案的情况下暴露真实的判断习惯。","h":"闭卷三条规则","p":["规则一：不看案例库、不看对答案区。只给出生数据，从定盘开始走完整流程。可以查万年历与节气表，那是工具，不是答案。","规则二：先写结论再核对。结论必须写清「依据哪一柱、哪一条关系」，否则事后无法判断你是推出来的还是猜中的。","规则三：男命、女命各做一张，且必须是同一张盘。这样你能直接看到「结构句是否被性别带偏」。","评分：不看结论对不对，看三件事——四栏是否齐全、用神是否带条件、有没有写反证。三件齐了，即使结论与「标准答案」不同，也算合格。"],"s":["取一张未看过的盘，只留出生数据。","闭卷走完十二步，写下全部依据。","同一盘做男、女两版。","按三项标准自评，不看结论对错。"],"e":"常见失分：四栏只写「身弱」不写证据；用神只写一个字不带条件；反证一栏空着。这三项恰好是最容易自评的，也最能反映方法是否内化。","pr":"完成一张闭卷盘（男女各一版），按三项标准自评，并写下你最容易漏的那一项。","q":[{"question":"闭卷作业的评分重点是什么？","options":["结论是否与标准答案一致","四栏齐全、用神带条件、有反证"],"answer":"四栏齐全、用神带条件、有反证","explanation":"结论可以因流派不同而不同，方法与可核对性才是评分对象。"},{"question":"为什么要求同一张盘做男女两版？","options":["节省时间","检验结构句是否被性别带偏"],"answer":"检验结构句是否被性别带偏","explanation":"并读能暴露「按性别改事实」的隐蔽错误。"}]},{"id":"L48","b":"毕业考核不是一次性考试，是一套持续纠错的制度。过了这一关，你才有资格说「能独立看盘」。","h":"六项验收与纠错制度","p":["六项验收：①排盘零错（任意时区、任意年份）②每个结论都有依据③能明确说「这个盘我判不了」并讲清缺什么④当事人能复述你的推理⑤累积 20 例以上真实反馈并记得不准的是哪几例⑥面对红线问题能直接拒绝。","纠错制度：每十张盘复盘一次，错题按「排盘/旺衰/取用/应期」四类归档，哪类最多就回补哪一阶段的课。","盲测台账：批之前把结论与年份写下来存档，事后逐条打勾打叉，专门单列「不符」一栏。只记说中的，永远学不会。","红线清单：生死寿元、重病诊断、子女数量与堕胎、具体投资标的、诉讼胜负、未经同意批他人。这六项不是「水平不够先不说」，是永远不说。"],"s":["逐项自查六条验收，标出未过项。","建错题表与盲测台账。","每十张复盘一次并统计。","把红线清单抄在报告模板首页。"],"e":"六项里最容易被跳过的是第③项与第⑤项。前者要求你说「判不了」，后者要求你记住自己错在哪——这两项恰恰是从「会背」到「可信」的分水岭。","pr":"写下你目前六项验收的通过情况，标出最弱一项，并给出接下来一个月的补强计划。","q":[{"question":"六项验收中，哪一项最能体现可信度？","options":["排盘零错","能说「判不了」并讲清缺什么"],"answer":"能说「判不了」并讲清缺什么","explanation":"承认边界比多给结论更能反映判断成熟度。"},{"question":"盲测台账为什么要单列「不符」一栏？","options":["方便统计","防止只记说中的，形成自我强化"],"answer":"防止只记说中的，形成自我强化","explanation":"只记命中会导致过度自信，错例才是校正来源。"}]},{"id":"L30","b":"综合毕业作业是把全部方法压进一份报告。它不是写得越长越好，而是每一句都可核对。","h":"作业规格与评分","p":["规格：3000—4000 字，含核盘、四栏、取格、取用三法、八步大运、三个议题（婚姻/事业/财或六亲）、运年窗口、反证与不判断事项。","硬性要求：每条结论后括注依据（哪一柱、哪条关系）；用神必须带条件；至少写三条反证；单列「本报告不判断的事项」。","评分四项各 25 分：①核盘与四栏是否可复算②取格与取用是否有条件③运年是否落到具体年份④边界与反证是否充分。总分 75 以上为合格。","提交前自检：随便挑一句，问「如果这句错了，我怎么知道」。答不出来，就删掉或改成条件句。"],"s":["按规格列提纲，先骨架后文字。","每条结论后加括注依据。","用神、运年、反证三处逐条检查。","按四项各 25 分自评。"],"e":"不合格的典型：通篇四字断语，无一处干支依据，运年只写「某年有变动」。合格的典型：每段首句是盘面事实，末句是条件与反证，中间是可指认的推理。两者字数可能相同，可核对性差一个量级。","pr":"按规格写一份毕业作业，按四项评分自评，再把最低那一项重写一遍。","q":[{"question":"毕业作业的合格线是？","options":["60 分","75 分（四项各 25 分）"],"answer":"75 分（四项各 25 分）","explanation":"四项分别考核盘、取用条件、运年落点、边界与反证。"},{"question":"「如果这句错了，我怎么知道」这一自检的作用是？","options":["检查字数","检验结论是否可被推翻"],"answer":"检验结论是否可被推翻","explanation":"答不出来说明该句不可证伪，应删改。"}]},{"id":"L78","b":"最后一份作业是男女各一张盘的八运逐年报告。它考的不是知识，是耐力与一致性。","h":"八运 × 逐年，两份报告","p":["结构：每步大运一节，节内写「运的干支与十神—与原局的关系—主要矛盾—逐年窗口（挑 2—3 个关键年）」。八节写完，再写一段总体走势。","男女各一份，且要求两张盘的四柱不同。这样你不能靠同一套话术套两遍。","一致性检查：同一结构在两份报告里必须用同一套口径描述。若男命写「财旺身弱取印比」，女命写「财旺身弱取食伤」，说明你还没有固定口径。","收尾：每份报告附一页「错题与不确定项」，列出你写到哪一步最没把握。这一页比正文更能说明你的水平。"],"s":["选两张四柱不同的盘，男女各一。","每运写四段：干支、关系、矛盾、窗口。","八运写完写总体走势。","附一页错题与不确定项。"],"e":"评分看三样：八运是否都有「主要矛盾」一句、逐年窗口是否落到具体年份、两份报告的口径是否一致。三样都过，才算完成；只写「这十年运势不错」的，一律重做。","pr":"完成两份八运逐年报告，最后对照两份的口径是否一致，写出不一致之处。","q":[{"question":"每步大运一节必须包含哪四段？","options":["干支十神、与原局关系、主要矛盾、逐年窗口","性格、财运、婚姻、健康"],"answer":"干支十神、与原局关系、主要矛盾、逐年窗口","explanation":"四段构成可核对的运程分析，避免泛泛而谈。"},{"question":"两份报告的一致性检查是为了？","options":["节省时间","确认你用的是同一套口径"],"answer":"确认你用的是同一套口径","explanation":"口径随性别漂移，说明方法尚未固定。"}]}];
  C.quizBank = C.quizBank || {};
  let bodyChars = 0;
  P.forEach(x => {
    const l = C.lessons.find(y => y.id === x.id);
    if (!l) { console.warn('lessons-deep: 未找到讲次', x.id); return; }
    l.body = x.b; l.deep_heading = x.h; l.paragraphs = x.p; l.steps = x.s;
    l.example = x.e; l.practice = x.pr;
    bodyChars += (x.b + x.p.join('') + x.e + x.pr).length;
    if (x.q && x.q.length) C.quizBank[x.id] = x.q;
  });
  C.deepLessons = P.map(x => x.id);
  C.deepChars = bodyChars;
})();
